'Custom_SMS_Payload_Hint' => 'Define the request body fields. Use {phone}, {message} and {sender} as placeholders; they will be replaced at send time.',
'Custom_SMS_Guide_Title' => 'How to configure',
'Custom_SMS_Guide_Intro' => 'Any SMS provider with an HTTP API can be connected. Open your provider\'s API documentation, copy the endpoint, method and field names, then map them below using the placeholders.',
'Custom_SMS_Guide_Placeholder_Phone' => 'the recipient\'s phone number',
'Custom_SMS_Guide_Placeholder_Message' => 'the SMS text',
'Custom_SMS_Guide_Placeholder_Sender' => 'the Sender ID entered above',
'Custom_SMS_Guide_Api_Url' => 'The full endpoint URL from your provider\'s documentation, e.g. https://api.provider.com/sms/send. Placeholders are also allowed directly in the URL, e.g. ...?to={phone}&text={message}.',
'Custom_SMS_Guide_Method' => 'POST is the most common. Choose GET only if your provider expects everything in the URL — the payload fields are then sent as query parameters.',
'Custom_SMS_Guide_Content_Type' => '"json" sends the payload as a JSON body (application/json). "form" sends it as a classic HTML form (application/x-www-form-urlencoded). Check which one your provider expects; it is ignored for GET.',
'Custom_SMS_Guide_Sender' => 'Your approved Sender ID or sending phone number. It only fills the {sender} placeholder — to be transmitted it must be used in the payload, headers or URL.',
'Custom_SMS_Guide_Success_Keyword' => 'Optional but recommended. Some providers reply "200 OK" even when sending fails. Enter a word or fragment that only appears in a successful response (e.g. success). If the response does not contain it, the SMS is treated as failed.',
'Custom_SMS_Guide_Headers' => 'Authentication headers required by your provider, e.g. Authorization = Bearer YOUR_API_KEY, or Api-Key = YOUR_API_KEY. Do not add Content-Type — it is set automatically.',
'Custom_SMS_Guide_Payload' => 'The request body fields, named exactly as in your provider\'s documentation. Use the placeholders as values, e.g. to = {phone}, message = {message}, from = {sender}.',
'Custom_SMS_Guide_Example' => 'Full example',
'Custom_SMS_Guide_Default_Note' => 'After saving, select "custom" as the Default SMS Gateway at the top of this page and submit — otherwise SMS will keep using the previously selected gateway.',
