'Restrict_Master_Data_By_Warehouse' => 'Restrict master data by warehouse',
'Restrict_Master_Data_By_Warehouse_Help' => 'When on, a user assigned to specific warehouses sees only the products, customers, suppliers, brands and categories connected to those warehouses. Records not yet used anywhere stay visible, so newly created ones are never hidden. Sales, purchases and returns are always restricted and are not affected by this switch.',
'Restrict_Products_By_Warehouse' => 'Restrict products by warehouse',
'Restrict_Products_By_Warehouse_Help' => 'Every product gets a home warehouse — the branch it was created for. When on, a user assigned to specific warehouses sees, sells and edits only the products whose home warehouse is theirs, plus products that hold real stock in one of their warehouses (transferred or purchased in). Users who may access all warehouses always see everything. The online store follows the same rule: it lists only the products of the warehouses selected in Store Settings.',
'Virtual_Combo_Stock' => 'Virtual combo stock',
'Virtual_Combo_Stock_Help' => 'When on, a combo product has no stock of its own: its availability is the number of combos its component products can still fill, and selling a combo takes stock from the components. When off, combos are assembled into stock with an Adjustment first.',
'Virtual_Combo_Stock_Warning' => 'Best chosen before selling combos. After combos have been sold or returned, switching makes later edits, deletions and returns of those documents reverse their stock the wrong way.',
'Virtual_Combo_Stock_Confirm_On_Title' => 'Turn on virtual combo stock?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'Combos will sell straight from their component products, and their own stock will no longer be used.',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'Turn off virtual combo stock?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'Combos will go back to their own stock, which has to be assembled from the components with an Adjustment before they can be sold.',
'Home_Warehouse' => 'Home warehouse',
'Home_Warehouse_Hint' => 'The branch this product belongs to. Users restricted to other warehouses will not see it unless stock is transferred to them.',
'Home_Warehouse_Required' => 'Choose the warehouse this product belongs to.',
'Combo_products_required' => 'Add at least one product to the combo.',
