'Tg_Guide_Step1_Title' => 'Create the bot',
'Tg_Guide_Step1_Body' => 'In Telegram, open a chat with {botfather}, send {newbot}, and pick a name and a username for the bot. BotFather replies with a {botToken} such as {example} — copy it.',
'Tg_Guide_Bot_Token_Lower' => 'bot token',
'Tg_Guide_Step2_Title' => 'Find the chat ID',
'Tg_Guide_Step2_Intro' => 'Where the messages go decides which ID you need:',
'Tg_Guide_Own_Chat' => 'Your own chat',
'Tg_Guide_Own_Chat_Item' => '{label} — send any message to your new bot first (a bot cannot start a conversation), then message {userinfobot}: it replies with your user ID.',
'Tg_Guide_Group' => 'A group',
