'Tg_Guide_Administrator' => 'administrator',
'Tg_Guide_GetUpdates_Intro' => 'For a group or channel, open this address in a browser with your own token in it, and refresh it after posting:',
'Tg_Guide_GetUpdates_Note' => 'Look for {chatId}. A group or channel ID is negative, e.g. {example} — copy all of it, minus sign included.',
'Tg_Guide_Step3_Title' => 'Connect it here',
'Tg_Guide_Step3_Body' => 'On the {settings} tab paste the bot token and the chat ID, choose {allEvents} or only the ones you want ({events}…), switch on {enable} and save. Then press {sendTest}.',
'Tg_Guide_State_Enabled' => 'enabled',
'Tg_Guide_State_Saved_Off' => 'saved, but switched off',
'Tg_Guide_State_Not_Configured' => 'not configured yet',
'Tg_Guide_Chat_Id' => 'chat {id}',
'Tg_Guide_How_Sent' => 'How messages are sent',
'Tg_Guide_A_Title' => 'Right away — nothing to install',
'Tg_Guide_A_Body' => 'A sale, purchase, payment or expense saved here — at the POS or in the admin — is sent to Telegram {rightAfter} it has been saved, in the same request. No cron entry, no queue worker, and the cashier never waits for Telegram: the sale has already been answered when the message goes out.',
'Tg_Guide_Right_After' => 'right after',
'Tg_Guide_B_Title' => 'The cron entry — for retries and background events',
'Tg_Guide_B_Body' => 'Two kinds of message wait on Telegram\'s own queue instead: a send that failed (Telegram unreachable for a moment), which is retried up to three more times over the next few minutes; and events raised outside the admin — orders imported from WooCommerce or Shopify, artisan commands. This cron entry sends them, and nothing else:',
'Tg_Guide_B_Note' => 'Every minute is right: a run with nothing waiting exits at once. On cPanel this goes in {cronJobs} — use the full path to PHP 8.2+ if {php} is older. On Windows, use Task Scheduler with program {php2}, arguments {args}, started in {path}.',
'Tg_Guide_N_Waiting' => '{n} waiting to be sent',
'Tg_Guide_Nothing_Waiting' => 'nothing waiting',
'Tg_Guide_N_Gave_Up' => '{n} gave up after retries',
'Tg_Guide_Growing_Hint' => '— if this number keeps growing, the cron entry is not running.',
'Tg_Guide_Without_Cron' => 'Without the cron entry, everything saved here still arrives instantly; you only lose the retries and the imported orders.',
'Tg_Guide_Else_Title' => 'Everything else',
'Tg_Guide_Else_Body' => 'Messages for events raised in the background are delivered by the platform — there is nothing to set up.',
'Tg_Guide_Not_Arrive' => 'If it does not arrive',
'Tg_Guide_Err_401' => '{code} — the bot token is wrong. Paste it again from BotFather.',
'Tg_Guide_Err_400' => '{code} — wrong chat ID, or the bot is not in the group. For a personal chat, message the bot first.',
'Tg_Guide_Err_403' => '{code} — add the bot back to the group, or as an admin of the channel.',
'Tg_Guide_Test_Works' => 'The test works but sales do not',
'Tg_Guide_Test_Works_Item' => '{label} — check the event is ticked (or {allEvents} is chosen) and the switch is on.',
'Tg_Guide_Imported_Never' => 'Imported orders never arrive',
'Tg_Guide_Imported_Never_Item' => '{label} — the cron entry above is not running.',
'Jumia_Hero_Title' => 'Jumia marketplace sync',
'Jumia_Hero_Desc' => 'Push prices and stock to your Jumia Seller Center listings and import marketplace orders as sales.',
'Jumia_Api_Url_Label' => 'API URL (your country\'s Seller Center endpoint)',
'Jumia_Account_Email' => 'Account email (User ID)',
'Jumia_Prices_Stock' => 'Prices & Stock',
'Jumia_Push_Card_Title' => 'Push prices & stock to Jumia',
'Jumia_Push_Desc' => 'Sends the current price and quantity for every product (and variant) that has a SKU matching the Jumia listing\'s {sellerSku}. Updates are submitted as Seller Center feeds and applied asynchronously — the feed ID is recorded in the Logs tab, and per-item rejections appear in Seller Center\'s feed status screen.',
'Jumia_Push_Prices_Stock' => 'Push prices & stock',
'Jumia_Orders_Desc' => 'Imports marketplace orders as sales (references like {ref}), matched to your products by Seller SKU. Already-imported and cancelled orders are skipped, so pulling regularly is safe. Payments are marked paid only for delivered orders (Jumia is COD-dominant).',
'Jumia_Guide_1' => 'In Jumia {sellerCenter}, open Settings → {integrationMgmt} and generate an API key.',
'Jumia_Guide_2' => 'Enter your country\'s API URL (e.g. {ng} for Nigeria, {ke} for Kenya, {eg} for Egypt), your Seller Center account email, and the key — then run {test}.',
'Jumia_Guide_3' => 'Make sure each Jumia listing\'s {sellerSku} equals the POS product code — that is the identity used for both stock pushes and order matching.',
'Jumia_Guide_4' => 'Push prices & stock after inventory changes; pull orders regularly (Jumia has no webhooks in this API).',
'Jumia_Guide_5' => 'Creating new listings stays in Seller Center — Jumia requires category-specific attributes and image review that only their portal handles well.',
'Mc_Hero_Title' => 'Mailchimp audience sync',
'Mc_Hero_Desc' => 'Keep a Mailchimp audience filled with your customers, so you can run email campaigns on your real customer base.',
'Mc_Account_Audience' => 'Account & audience',
'Mc_Api_Key_Placeholder' => 'e.g. a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'Audience',
'Mc_N_Members' => '({n} members)',
'Mc_Load_Audiences_To_Pick' => 'Load audiences to pick one',
'Mc_Load_Audiences' => 'Load audiences',
'Mc_Double_Opt_In_Label' => 'Double opt-in — new members get a confirmation email before joining',
'Mc_Recommended_GDPR' => '(recommended for GDPR)',
'Mc_Auto_Sync_New' => 'Auto-sync new customers as they are created',
'Mc_With_Email' => 'With an email',
'Mc_Push_Desc' => 'Upserts every customer that has an email address into the selected audience (name and phone included). Existing members keep their subscription status — nobody who unsubscribed is re-subscribed. Customers without an email are left out.',
'Mc_Double_Opt_In_Off' => 'Double opt-in is off',
'Mc_Double_Opt_In_Off_Desc' => 'New members will be added as subscribed without a confirmation email. Only do this for customers who already agreed to receive marketing.',
'Mc_Guide_1' => 'In Mailchimp, open {path} and create a key (it ends in {suffix} — that suffix is your datacenter).',
'Mc_Guide_2' => 'Paste the key here, save, then click {load} and pick the audience to fill.',
'Mc_Guide_3' => 'Leave {doi} on unless your customers have already consented to marketing emails.',
'Mc_Double_Opt_In_Lower' => 'double opt-in',
'Mc_Guide_4' => 'Run {push} for the initial fill; turn on {autoSync} so new customers join automatically.',
'Mc_Auto_Sync_Lower' => 'auto-sync',
'Mc_Consent_Matters' => 'Consent matters',
'Mc_Consent_Desc' => 'Emailing people who never agreed to marketing can violate GDPR/CAN-SPAM and get your Mailchimp account suspended. Double opt-in shifts the confirmation to Mailchimp — the safe default.',
'Mc_No_Audiences' => 'No audiences found on this account.',
'Presta_Hero_Desc' => 'Sync products, stock and orders with your PrestaShop store over its webservice API.',
'Presta_Webservice_Key' => 'Webservice key',
'Presta_Key_Placeholder' => 'From Advanced Parameters → Webservice',
'Presta_Key_Help' => 'Enable the webservice in PrestaShop (Advanced Parameters → Webservice), create a key with permissions on products, stock_availables, orders and customers, and paste it here. Stored write-only.',
'Presta_Shop_Language_ID' => 'Shop language ID',
'Presta_Language_Help' => 'Language id used for product names when pushing (1 = the shop\'s first language).',
'Presta_Push_Desc' => 'Creates missing simple products on PrestaShop (with their current stock). Already-linked products and variant products are skipped — keep editing product details in PrestaShop, or pull to refresh the local copy.',
'Presta_Pull_Desc' => 'Imports PrestaShop products, matching existing ones by reference (SKU) and creating the rest. Combinations are imported as their parent product.',
'Presta_Reset_Confirm' => 'Reset product links? Order history keeps its links.',
'Presta_Stock_Desc' => 'Updates the shop\'s stock (stock_availables) for every linked product.',
'Presta_Orders_Desc' => 'Imports shop orders as sales (references like {ref}), newest first. Already-imported and cancelled orders are skipped, so pulling regularly is safe. PrestaShop has no webhooks — run this after busy periods.',
'Presta_Guide_1' => 'In your PrestaShop back office, open {path} and enable the webservice.',
'Presta_Guide_2' => 'Add a new key, granting {vae} on {products} and {stock}, and {view} on {orders} and {customers}.',
'Presta_Guide_3' => 'Paste the store URL and the key on the Connection tab, save, and run {test}.',
'Presta_Guide_4' => 'Pull products first if the shop already has a catalog (matches by reference/SKU); push to create missing simple products.',
'Presta_Guide_5' => 'Push stock whenever quantities change, and pull orders regularly — PrestaShop has no webhooks, so orders only arrive when you pull.',
'Presta_Identity_Title' => 'Product identity is the reference (SKU)',
'Presta_Identity_Desc' => 'The POS product code is matched to PrestaShop\'s reference. Keep references consistent on both sides; combinations (variants) are matched in orders by reference but are not pushed in this version.',
