'Gs_Redirect_Uri_Title' => 'Redirect URI for the Google OAuth client',
'Gs_Export_Desc' => 'Each export rewrites its tab from scratch (header + all rows), so the sheet is always a complete, current snapshot. Large datasets are sent in batches — leave the page open until the counter stops.',
