'Gs_Job_Customers_Desc' => 'All customers with their contact details.',
'Gs_Guide_1' => 'Create a project on {console} and enable the {api} (APIs & Services → Library).',
'Gs_Guide_2' => 'Configure the {consent} (External). While it stays in "Testing", add your Google account as a test user — note that testing-mode refresh tokens expire after 7 days, so {publish} the app for a permanent connection.',
