'Xero_Payment_Account_Code' => 'Payment account code (optional)',
'Xero_Payment_Code_Placeholder' => 'e.g. 090',
'Xero_Payment_Account_Help' => 'A bank account code. When set, paid sales also record a payment on the invoice; leave empty to sync invoices only.',
'Xero_Auto_Sync' => 'Auto-sync new sales as invoices',
'Xero_Auto_Sync_Hint' => '(queued in the background as sales are created)',
