'Xero_Disconnect_Confirm' => 'Disconnect the Xero organisation? Sync stops until you reconnect.',
'Xero_Redirect_Uri_Title' => 'Redirect URI for the Xero app',
'Xero_Redirect_Help' => 'Create a "Web app" on {link} and register this redirect URI. Note: Xero access tokens auto-refresh, but a connection idle for over 60 days must be reconnected.',
'Xero_Contacts_In_Xero' => 'Contacts in Xero',
'Xero_Invoices_In_Xero' => 'Invoices in Xero',
'Xero_Payments_Recorded' => 'Payments recorded',
'Xero_Push_Customers_Desc' => 'Creates or updates a Xero contact for every customer. A customer whose name already exists in Xero is linked to that contact.',
'Xero_Push_Sales_As_Invoices' => 'Push sales as invoices',
'Xero_Push_Invoices_Desc' => 'Creates one AUTHORISED invoice per sale (invoice number = the sale Ref), with the sale\'s line items plus shipping, discount and tax lines so the Xero total matches the sale total. Sales already in Xero are skipped — invoices are never edited. Missing contacts are created on the fly.',
