'Fbr_Guide_What_Title' => 'What is FBR Digital Invoicing?',
'Fbr_Guide_What_Body' => 'Under SRO 69(I)/2025, the Federal Board of Revenue (Pakistan) requires integrated businesses to report sales invoices electronically in real time through the PRAL Digital Invoicing (DI) API. Each accepted sale receives an official FBR invoice number, and receipts must display that number together with a verification QR code.',
'Fbr_Guide_Steps_Title' => 'Steps to go live',
'Fbr_Guide_Step_1' => 'Register on the FBR IRIS e-invoicing portal and obtain a {sandbox} security token.',
'Fbr_Guide_Step_2' => 'Configure your seller profile on the Configuration tab (NTN/CNIC, business name, province, address), paste the token, and enable the integration with the environment set to {sandbox}.',
'Fbr_Guide_Step_3' => 'Make test sales covering the scenario(s) FBR assigned to you (pick the scenario in the Sandbox Scenario field). Check the Documents tab to confirm they come back {valid}.',
'Fbr_Guide_Step_4' => 'Once FBR approves your sandbox testing, obtain the {production} token from the portal, paste it here, and switch the environment to {production}.',
'Fbr_Guide_Step_5' => 'Receipts automatically show the FBR invoice number and QR code once a sale is accepted — no extra steps needed at the point of sale.',
'Fbr_Sandbox_Lower' => 'sandbox',
'Fbr_Production_Lower' => 'production',
'Fbr_Guide_Note_1' => 'Set HS codes per product on the product form (field "HS Code"). The Default HS Code configured here is only used for products without one.',
'Fbr_Guide_Note_2' => 'Unregistered walk-in customers are reported to FBR as "Unregistered".',
'Fbr_Guide_Note_3' => 'Registered buyers need their NTN entered in the customer\'s Tax Number field so they are reported as registered.',
'Fbr_Guide_Note_4' => 'Failed or invalid submissions can be retried from the Documents tab after fixing the cause; the Logs tab shows the raw API exchanges for troubleshooting.',
