'Woo_Automatic_Sync' => 'Automatic sync',
'Woo_Auto_Sync_Intro' => 'Push changes made in your POS to WooCommerce as they happen, without opening this page. Each push runs right after the action is saved, so the cashier never waits for WooCommerce. Results appear in the Logs tab.',
'Woo_Auto_Sync_Products_Help' => 'A product created, edited or duplicated here is sent to WooCommerce (details, price, variants, images, stock). Bulk imports are not pushed; after an import, use Sync — POS → WooCommerce in the Products tab.',
'Woo_Auto_Sync_Stock_Help' => 'Any stock movement (POS sale, sale, return, purchase, adjustment, transfer) updates the quantity of the products involved on WooCommerce. Only products already linked to WooCommerce are updated.',
'Woo_Sync_Tuning' => 'Sync tuning',
'Woo_Sync_Tuning_Intro' => 'The defaults suit most stores. Change these only if sync is slow or times out on your hosting. Every value is capped to a safe range, and clearing a field restores its default.',
'Woo_Sync_Guide' => 'WooCommerce Sync Guide',
'Woo_Guide_Getting_Keys' => 'Getting API keys',
'Woo_Guide_Keys_1' => 'In WooCommerce: WooCommerce → Settings → Advanced → REST API.',
'Woo_Guide_Keys_2' => 'Add key, choose Read/Write, then copy Consumer key and Consumer secret.',
'Woo_Guide_Keys_3' => 'Store URL: your site URL with no trailing slash (e.g. {example}).',
'Woo_Guide_WP_Title' => 'WP Username and Application Password (optional)',
'Woo_Guide_WP_Intro' => 'These fields are used only for product images. The WooCommerce API (Store URL + Consumer key/secret) handles sync for products, stock, categories, brands, customers, and orders; the WordPress REST API handles the Media Library (search and upload images).',
'Woo_Guide_WP_1' => 'When syncing products or stock, the system can attach product images: it first searches the WordPress Media Library for an existing image by filename; if not found, it uploads the image via the WordPress API.',
'Woo_Guide_WP_2' => 'Use a WordPress user that can manage media (e.g. Administrator). Create an Application Password in WordPress: Users → Profile (or your user) → Application Passwords — add a new one and paste it here.',
'Woo_Guide_WP_3' => 'If you leave these blank, sync still works for all data (products, stock, categories, brands, customers, orders); only product image attachment (search/upload) is skipped.',
'Woo_Guide_How_To_Enable' => 'How to enable',
'Woo_Guide_Enable_1' => 'Enter Store URL, Consumer key, and Consumer secret above, then click Save.',
'Woo_Guide_Enable_2' => 'Use Test Connection to verify credentials.',
'Woo_Guide_Enable_3' => 'Use manual sync from any tab when you need to sync.',
'Woo_Guide_Enable_4' => 'Turn on Automatic sync above to push new and edited products and every stock change to WooCommerce as they happen.',
'Woo_Guide_Manual_Sync' => 'Manual sync (on demand)',
'Woo_Guide_Manual_1' => 'Sync works in both directions: POS → WooCommerce and WooCommerce → POS.',
'Woo_Guide_Manual_2' => 'Manual sync is available in all WooCommerce tabs (Products, Stock, etc.); use the sync actions in each tab to run sync on demand.',
'Woo_Guide_Auto_1' => 'Products: when on, a product you create, edit or duplicate here is sent to WooCommerce right after you save it, followed by its stock.',
'Woo_Guide_Auto_2' => 'Stock: when on, every stock change (POS sale, sale, return, purchase, adjustment, transfer) updates the quantity on WooCommerce. Only products already linked to WooCommerce are updated.',
'Woo_Guide_Auto_3' => 'Automatic sync sends changes from the POS to WooCommerce only. Bringing data from WooCommerce into the POS (orders, customers, products) is always done with the buttons in the Orders, Customers and Products tabs.',
'Woo_Guide_Auto_4' => 'Bulk product imports are not sent automatically. After an import, use Sync — POS → WooCommerce in the Products tab.',
'Woo_Guide_Auto_5' => 'Each automatic push is recorded in the Logs tab, so you can check what was sent and spot errors.',
'Woo_Guide_First_Setup' => 'First setup',
'Woo_Guide_First_1' => 'Run these once, in this order, so your existing catalogue is linked: Sync — POS → WooCommerce in the Categories tab, then the Brand tab, then the Products tab, and finally Sync Stock in the Stock tab. After that, turn on Automatic sync above to keep WooCommerce up to date.',
'Woo_Guide_First_2' => 'Large product and stock syncs run in small batches and show their progress in the tab. Keep the page open until the sync finishes; you can stop it at any time.',
'Woo_Guide_First_3' => 'If a sync stops moving for several minutes, check the Logs tab, then contact support.',
'Woo_Guide_Notes_1' => 'Changing Store URL or API keys resets mappings (products, categories, brands, customers); items will sync again to the (new) store.',
'Woo_Guide_Notes_2' => 'Keep SKUs consistent between the POS and WooCommerce to avoid duplicate products and to relink safely.',
