'Pg_Intro_Title' => 'Every gateway here is offered at the ONLINE STORE checkout once its credentials are stored and its switch is on.',
'Pg_Intro_Desc' => 'Each tab has its own on/off switch, saved the moment you flip it: switching a gateway off leaves its credentials in place, the checkout simply stops offering it. Stripe keys are shared globally (admin and online store use the same Stripe integration). Offline Payments holds cash on delivery and mobile money, which are paid outside the system.',
