'Shp_Stock_Only_On_Push' => 'Stock reaches Shopify only when the Inventory push step runs',
'Shp_Stock_Lag_Desc' => 'A sale at the counter stays invisible to the shop until then — up to {n} minutes, so the last unit can still be sold online twice. Switch on {setting} and every sale, return and adjustment is sent within seconds instead.',
