'Shp_Hook_Register_Cc' => 'Click “Register webhooks” below — nothing needs to be entered in Shopify.',
'Shp_Hook_Register_Token' => 'Click “Register webhooks” below, and paste the app\'s API secret key into the store settings as the signing secret.',
'Shp_Hook_Note_Register' => 'Registering creates the subscriptions in Shopify and points them at this address automatically. Do not add it by hand under Shopify → Settings → Notifications → Webhooks: those are signed with a different secret and every delivery would be refused.',
'Shp_Hook_Verified_Cc' => 'Deliveries are verified with the app\'s client secret, which is already stored.',
'Shp_Hook_Verified_Token' => 'Deliveries without a valid signature are refused, so the secret must be set before webhooks do anything.',
'Shp_Hook_Retries' => 'Shopify retries until it gets a 2xx, and each delivery is recorded once — a repeated event is a no-op, not a duplicate order.',
'Shp_No_Signing_Secret' => 'No signing secret stored',
'Shp_No_Signing_Secret_Desc' => 'Subscriptions can be created without one, but every delivery will be refused until the app\'s API secret key is saved on this store (a Dev Dashboard app\'s client secret already covers this).',
