'Shp_Domain_Hint' => '{domain} — the admin URL works too',
'Shp_App_Credentials' => 'App credentials',
'Shp_Auth_Client_Credentials' => 'Client ID + client secret (Dev Dashboard app)',
'Shp_Auth_Token' => 'Admin API access token (legacy custom app)',
'Shp_Cc_Alert' => 'Since January 2026 Shopify no longer creates custom apps in the admin. Create the app in the {dashboard}, grant its Admin API scopes, install it on this shop, then copy the Client ID and Client secret from its {settings} page. The ERP fetches a fresh access token itself every 24 hours. The app and the shop must belong to the same Shopify organisation.',
'Shp_Leave_Blank_Keep_Stored' => 'Leave blank to keep the stored one.',
'Shp_Client_Id_Placeholder' => 'From the app\'s Settings page',
'Shp_Client_Secret_Hint' => 'Also signs webhooks, so no separate signing secret is needed.',
'Shp_Masked_Unchanged' => '•••••••••••••• (unchanged)',
'Shp_Token_Keep_Hint' => 'Leave blank to keep the token already stored.',
'Shp_Token_Legacy_Hint' => 'Only for custom apps created in Shopify admin before 2026 (Apps → Develop apps → API credentials). New apps do not show a token; use the client ID + secret instead.',
'Shp_Webhook_Signing_Secret' => 'Webhook signing secret',
'Shp_Webhook_Secret_Optional_Hint' => 'Optional here — the client secret above signs webhooks for a Dev Dashboard app.',
'Shp_Webhook_Secret_Required_Hint' => 'Required before webhooks are accepted — unsigned deliveries are refused.',
'Shp_Will_Be_Cleared' => 'Will be cleared on save',
'Shp_Clear_Stored_Secret' => 'Clear the stored secret',
'Shp_Keep_It' => 'Keep it after all',
'Shp_Domain_Locked' => 'The domain is locked because changing it invalidates every mapping for this shop.',
'Shp_Change_Anyway' => 'Change it anyway',
'Shp_Domain_Change_Warning' => 'Saving a different domain deletes all record mappings for this connection — the stored ids belong to the old shop.',
'Shp_ERP_Warehouse' => 'ERP warehouse',
'Shp_ERP_Warehouse_Hint' => 'Stock levels and imported orders belong to this warehouse.',
'Shp_Available_After_Connecting' => 'Available after connecting',
'Shp_Fetch_Locations' => 'Fetch locations from Shopify',
'Shp_Price_Sent' => 'Price sent to Shopify',
'Shp_Create_Missing_Products' => 'Create ERP products for Shopify products that do not match a SKU',
'Shp_Create_Missing_Customers' => 'Create ERP customers for Shopify customers that do not match an email',
'Shp_Create_Missing_Customers_Hint' => 'With this off, an order from an unknown customer is skipped rather than guessed at.',
'Shp_Entities_Lead' => 'Only the entities switched on here can be synced — a shop you just pull orders from should not have a stray product push rewriting its catalogue.',
'Shp_Sync_On_Schedule' => 'Sync automatically on a schedule',
'Shp_Scheduler_Hint' => 'The scheduler checks every 5 minutes, which is the finest the intervals below can use. Syncs can always be started by hand.',
'Shp_Instant_Push_Hint' => 'A sale, return or adjustment sends a stock push for just those products the instant it is saved, so the shop is right within seconds instead of at the next scheduled run. Nothing else to install — the push runs after the sale has been answered, so the till never waits for Shopify.',
'Shp_Switch_Inventory_First' => 'Switch Inventory on under {tab} first.',
'Shp_Leave_Off_Lag' => 'Leave it off and a POS sale reaches Shopify only on the next Inventory push — up to {n} minutes later.',
'Shp_Default_Interval' => 'Default interval (minutes)',
'Shp_Default_Interval_Hint' => 'Used by every step that does not set its own.',
'Shp_What_Runs_Auto' => 'What runs automatically',
'Shp_Plan_Hint' => 'Each step is one entity in one direction. Orders only ever come {from} Shopify.',
'Shp_From' => 'from',
'Shp_Add_Step' => 'Add step',
'Shp_Using_Default_Plan' => 'Using the default plan',
'Shp_Default_Plan_Desc' => 'Orders are pulled in and stock is pushed out, every {n} minutes. Add a step to choose your own — clearing the list again restores this default.',
'Shp_N_Min' => '{n} min',
'Shp_Step_Entity_Off' => '{entity} is switched off on the previous tab — this step will be skipped.',
'Shp_Inactive_Lc' => 'inactive',
'Shp_No_Locations' => 'That shop reports no locations',
'Shp_Could_Not_Load_Locations' => 'Could not load locations — check the connection first',
'Shp_Store_Updated' => 'Store updated',
'Shp_Store_Connected' => 'Store connected',
'Shp_Could_Not_Save_Store' => 'Could not save this store',
'Shp_G_Lead_Store' => 'What this shop needs in order to keep itself in step. Everything here is specific to this store — the webhook URL and ids are real.',
'Shp_G_Lead_Store_Cmd' => 'What this shop needs in order to keep itself in step. Everything here is specific to this store — the webhook URL and ids are real, so the commands can be copied straight onto the server.',
'Shp_G_Lead_Generic' => 'How a Shopify shop keeps itself in step with the ERP. Pick a store above to see its own state, or read it as it is — the webhook URL is the same whichever store you connect.',
'Shp_G_Lead_Generic_Cron' => 'How a Shopify shop keeps itself in step with the ERP. Pick a store above to see its own state, or read it as it is — the webhook URL and the cron line are the same whichever store you connect.',
'Shp_G_Ways_Note' => 'Most shops run both: the first keeps the shop current minute to minute, the second catches whatever the first missed — a webhook that never arrived, an edit made directly in the Shopify admin, a night when the site was down.',
'Shp_G_Both_Need' => 'Both ways need this first',
'Shp_G_Credentials' => 'Shopify credentials',
'Shp_G_Cred_Intro' => 'Since January 2026 Shopify no longer creates custom apps inside the admin, so there are two kinds of connection:',
'Shp_G_Cred_Dev' => '{app} (any shop connected now) — {path}. Grant the Admin API scopes for what this store syncs, install the app on the shop, then copy the {clientId} and {clientSecret} from the app\'s Settings page into {edit}. The ERP exchanges them for an access token itself and renews it before it expires every 24 hours. The client secret also signs webhooks, so nothing else is needed. The app and the shop must sit in the same Shopify organisation.',
'Shp_G_Dev_App' => 'Dev Dashboard app',
'Shp_G_Cred_Legacy' => '{app} (created in the admin before 2026) — keeps working unchanged with its {token} ({prefix}) and its {secret} as the webhook signing secret. Not the same value as the token, and getting them the wrong way round is the usual reason webhooks are refused.',
'Shp_G_Legacy_App' => 'Legacy custom app',
'Shp_G_Api_Secret_Key' => 'API secret key',
'Shp_G_Stored' => 'stored',
'Shp_G_Missing_Refused' => 'missing — deliveries will be refused',
'Shp_G_Targets' => '{path} The ERP warehouse whose stock this shop sells, and the Shopify location that stock is written to. Inventory sync and order import both refuse to run without them.',
'Shp_G_Currently' => 'Currently: warehouse {warehouse}, location {location}',
'Shp_G_Not_Set_Lc' => 'not set',
'Shp_G_Ready' => 'ready',
'Shp_G_Incomplete' => 'incomplete',
'Shp_G_Manual_Syncs' => 'Syncs you start by hand',
'Shp_G_Manual_Body' => 'A sync started from the {centre} answers at once and runs in the background, in short slices that each carry on from where the last one stopped. A big catalogue is never cut off part-way by a web request that runs out of time, and closing the page does not stop it.',
'Shp_G_Worker_Managed' => 'Your platform runs the worker for that, so there is nothing to install.',
'Shp_G_Worker_Cron' => 'The worker for that is one more cron line:',
'Shp_G_Cron_Copied' => 'Cron line copied',
'Shp_G_Worker_Busy' => 'If the worker is busy, the open Sync Centre page carries the run on itself after a few seconds, one short request at a time — so a sync always finishes while you watch it.',
'Shp_G_Pick_How' => 'Then pick how it keeps in step',
'Shp_G_Right_Away' => 'Right away',
'Shp_G_Stock_Live' => 'stock live',
'Shp_G_Stock_Not_Live' => 'stock not live',
'Shp_G_Realtime_Lead' => 'Each change is sent as it happens, in seconds. Two halves, and they are separate switches: {webhooks} bring the shop\'s own events in, and {push} sends stock out.',
'Shp_G_Webhooks_Lc' => 'webhooks',
'Shp_G_Instant_Push_Lc' => 'instant stock push',
'Shp_G_Webhooks_Heading' => 'Webhooks — the shop → the ERP',
'Shp_G_Webhooks_Body' => 'Orders, order status changes, and product, customer and stock edits made in Shopify. Open the store and press {button} on its {tab} — safe to press twice. Shopify posts to:',
'Shp_G_Webhooks_Tab' => 'Webhooks tab',
'Shp_G_Webhooks_Note' => 'The address must be reachable from the internet over HTTPS — Shopify will not deliver to {localhost} or a {test} domain. Each delivery is recorded once, so Shopify\'s retries cannot create a duplicate order, and a failed one can be replayed. Deliveries are refused until the signing secret from step 1 is stored.',
'Shp_G_Push_Heading' => 'Instant stock push — the ERP → the shop',
'Shp_G_People_Miss' => 'This is the setting people miss',
'Shp_G_Push_P1' => 'A POS sale does {not} reach Shopify by itself. Left off, the shop only finds out on the next Inventory push step — and in that window it can sell a unit you have already sold at the till.',
'Shp_G_Not' => 'not',
'Shp_G_Push_P2' => 'Tick {setting} on {path}. That is the whole setup — no worker, no cron. Every sale, return and adjustment then sends a push of just those products, right after the sale is saved, and a twenty-line sale costs one push, not twenty. The till never waits for it.',
'Shp_G_This_Store' => 'This store:',
'Shp_G_Push_On' => 'on — stock pushed on change',
'Shp_G_Push_Off' => 'off — stock on the schedule only',
'Shp_G_Push_Note' => 'Only products that already have a Shopify mapping, and only movements in this store\'s warehouse, are pushed. Bulk operations — deleting a product, resetting a warehouse — write stock without firing an event, which is one reason to keep the scheduled inventory step as well.',
'Shp_G_Nothing_Else' => 'Nothing else to install',
'Shp_G_Nothing_Else_Body' => 'Neither half needs a queue worker or a cron entry. A webhook coming in is handled in the request Shopify makes; a stock push going out runs in the same process that served the sale, {after} the response has gone back — so the till is never waiting on Shopify, and a shop that stops answering is given up on after ten seconds and left to the next scheduled inventory push.',
'Shp_G_After' => 'after',
'Shp_G_Exception' => 'One exception: a stock change made by a background task has no response to come after, so it is queued on {queue} instead.',
'Shp_G_Queue_Managed' => 'Your platform already runs a worker on that queue, so those go out on their own too.',
'Shp_G_Queue_Cron' => 'If you want those to go out promptly too, drain that queue:',
'Shp_G_On_Schedule' => 'On a schedule',
'Shp_G_On_Lc' => 'on',
'Shp_G_Off_Lc' => 'off',
'Shp_G_Scheduled_Lead' => 'Everything is re-checked every so often, both ways. Slower than real time, but it is what pushes stock out on shops that do not use instant push, what catches a missed webhook, and the only way to move a whole catalogue.',
'Shp_G_Nothing_To_Install' => 'Nothing to install',
'Shp_G_Managed_Body' => 'The scheduler is run for you: every five minutes your platform asks each store whether any step of its plan is due, and runs the ones that are. There is no cron entry to add and no server to keep.',
'Shp_G_Managed_Note' => 'Five minutes is also the finest resolution a plan can use, because five minutes is the shortest step interval. Longer intervals are honoured exactly — a step set to 30 minutes is checked six times and runs once.',
'Shp_G_Cron_Entry' => 'The cron entry',
'Shp_G_Cron_Body' => 'Nothing scheduled runs without it. One line, this module only — add it next to whatever else you have chosen to schedule:',
'Shp_G_Cron_Note' => 'Every five minutes is the finest resolution a plan can use, because five minutes is the shortest step interval. A coarser entry simply becomes the floor — with {every15}, a step set to 5 minutes runs every 15. On Windows use Task Scheduler: program {php}, arguments {args}, started in {path}.',
'Shp_G_Switch_On' => 'Switch it on, and choose the plan',
'Shp_G_Plan_Body' => '{path} The switch decides whether the scheduler may act at all; the plan decides what it does. A {step} is one entity in one direction with its own interval — {ex1}, {ex2}. The default interval is used by any step that leaves its own box empty.',
'Shp_G_Step_Lc' => 'step',
'Shp_G_Ex1' => 'Orders · Shopify → ERP every 15 min',
'Shp_G_Ex2' => 'Inventory · ERP → Shopify every 30 min',
'Shp_G_Plan_Note' => 'Leave the plan empty and the store pulls orders and pushes stock at the default interval, which is what most shops want. Orders are pull-only: Shopify is where a customer places one.',
'Shp_G_Schedule_On' => 'schedule on',
'Shp_G_Schedule_Off' => 'schedule off — manual only',
'Shp_G_When_Runs' => 'When a step actually runs',
'Shp_G_When_Body' => 'A step is due when that same step last {started} longer ago than its interval, read from the run history. So a sync you start by hand postpones the next automatic one, and a step that keeps failing is retried on its interval rather than every tick. The store\'s Overview shows each step\'s last run, next due time, and the reason it is blocked when it is. Run the first catalogue push by hand from the Sync Centre — as a dry run first — before putting it on a schedule.',
'Shp_G_Started_Lc' => 'started',
'Shp_G_Where_Setting' => 'Where each setting lives',
'Shp_G_Where_Note' => 'All of these are on an existing store: {path}, then the pencil (or {edit} on the store\'s own page).',
'Shp_G_Product_Images' => 'Product images',
