'Agt_Series' => 'Series',
'Agt_Series_Hint' => 'AGT authorises one numbering series per document type, year and establishment. Invoices cannot be issued without an active series for their type and year.',
'Agt_Request_Series' => 'Request series from AGT',
'Agt_Add_Series' => 'Add existing series',
