'Agt_Correct_Confirm' => 'Issue a correction with a new number for this rejected document?',
'Agt_Correct' => 'Correct',
'Agt_Guide_What_Title' => 'What this does',
'Agt_Guide_What_Body' => 'Every completed sale is issued as an AGT electronic invoice (FR when paid at creation, otherwise FT) and every received return as a credit note (NC). Each document gets the next number of its AGT series, is signed with your AGT key and sent to AGT, which validates it a few minutes later. The receipt and the PDF invoice print the AGT number, the security extract and a QR code.',
'Agt_Guide_Steps_Title' => 'Setup',
'Agt_Guide_Step_1' => 'Join e-invoicing (adesão) on the Portal do Contribuinte and download your AGT private key.',
'Agt_Guide_Step_2' => 'Enter your NIF, establishment and the key on the Configuration tab, choose Homologação, save and use Test Connection.',
'Agt_Guide_Step_3' => 'On the Series tab, request one series per document type you use (FR, FT, NC) for the current year.',
'Agt_Guide_Step_4' => 'Map your IVA rates to AGT codes and set the exemption code for 0% lines.',
'Agt_Guide_Step_5' => 'Turn the module on in System Settings > Features, make a test sale and check that it becomes valid on the Documents tab.',
'Agt_Guide_Step_6' => 'When AGT approves you for production, switch to Produção and request production series.',
'Agt_Guide_Note_1' => 'A communicated sale or return can no longer be edited or deleted. Correct it with a sale return (credit note).',
'Agt_Guide_Note_2' => 'Documents rejected by AGT are corrected with a new number that references the rejected one; the old number is never reused.',
'Agt_Guide_Note_3' => 'Offline POS sales are communicated when they sync. AGT penalises documents sent more than 24 hours late.',
'Agt_Guide_Note_4' => 'A line cannot carry both a product tax and the order tax; AGT needs one IVA rate per line. Shipping is sent as an exempt line.',
'Agt_Guide_Note_5' => 'AGT totals are computed per line and may differ from the system total by a few cents of rounding.',
