'Dgi_Api_Pending_Body' => 'The DGI publishes the e-MCF developer API only to registered developers (developper.dgirdc.cd). Until it is connected, invoices carry your NIF / RCCM / Id. Nat. mentions but no DEF number, authentication code or QR.',
