'Dgi_Guide_What_Title' => 'What this does today',
'Dgi_Guide_What_Body' => 'With the module on, receipts and PDF invoices print the seller NIF, RCCM and Id. Nat. required on the facture normalisée. Full certification (DEF number, counters, authentication code and QR returned by the DGI) is added once the e-MCF developer API is connected.',
'Dgi_Guide_Steps_Title' => 'Getting access to the e-MCF',
