    'VG_Intro' => 'A variable product is sold as several variants. Build them from options (recommended) or as a simple list of names. Every variant has its own code, prices, image and stock.',
    'VG_Options_Title' => 'Options mode (Color, Size...)',
    'VG_Opt_Step1' => 'Keep the switch in the card header on "Options".',
    'VG_Opt_Step2' => 'Type an option name such as Color or Size, or pick one of the suggestions.',
