    'Comm_G_S_Pending' => 'Just calculated from a sale. Nobody has checked it yet. Approve it or cancel it in the Commission Report.',
    'Comm_G_S_Approved' => 'Checked and agreed. It is owed to the agent and can be included in a Commission Receipt. If the sale changes and the amount changes, it goes back to Pending for another review.',
    'Comm_G_S_Paid' => 'Included in a Commission Receipt. Final: paid commissions are never changed. If the sale changes afterwards, the difference is added as a separate Adjustment.',
    'Comm_G_S_Cancelled' => 'Will not be paid. It stays cancelled when payments or returns come in later. Saving the sale in Edit Sale, or ticking it in the report and clicking Recalculate, works it out again.',
    'Comm_G_Field' => 'Field',
    'Comm_G_T_Programs' => 'Commission programs',
    'Comm_G_Programs_Body' => 'A program is a container for rules, usually one per period or campaign. A rule only works while its program is Active and the sale\'s date falls inside the program\'s dates. Several programs can be active at the same time, and all of them apply.',
    'Comm_G_F_Program_Name' => 'Any name that helps you recognise the program, for example "Q4 2026" or "Black Friday".',
    'Comm_G_F_Program_Active' => 'Untick it to pause every rule in the program at once. Commissions already created are not affected.',
    'Comm_G_F_Program_From' => 'Sales dated before this day are ignored by the program. Leave it empty for no start date.',
    'Comm_G_F_Program_To' => 'Sales dated after this day are ignored by the program. Leave it empty for a program that never ends.',
    'Comm_G_T_Agents' => 'Sales agents',
    'Comm_G_Agents_Body' => 'A sales agent is the person who earns commission. An agent does not need to be a user of the system: outside referrers or resellers can be agents too, and they earn whenever they are picked on a sale.',
    'Comm_G_F_Agent_Name' => 'The name shown on sales, the report and receipts.',
    'Comm_G_F_Agent_Code' => 'Optional reference such as an employee number. Searchable in the agents list.',
    'Comm_G_F_Agent_User' => 'Links the agent to a staff user. Sales that user makes (or is chosen as salesperson for on the POS) are then credited to this agent automatically.',
    'Comm_G_F_Agent_Active' => 'Inactive agents earn nothing on new sales and disappear from the agent pickers. Their past commissions stay.',
    'Comm_G_T_Rules' => 'Commission rules: every field explained',
    'Comm_G_Rules_Body' => 'A rule decides how much is paid on a sale. Use the "Try a rule" box above to check a rule before you save it.',
    'Comm_G_F_Rule_Program' => 'The program the rule belongs to. The rule only works while that program is active and in date.',
    'Comm_G_F_Rule_Type' => 'Percentage pays a share of the base amount. Fixed pays the same amount on every qualifying sale, whatever its size.',
    'Comm_G_F_Rule_Source' => 'What the percentage is taken from. Sale Total is the sale\'s grand total. Paid Amount is what the customer had paid when the commission was calculated.',
    'Comm_G_F_Rule_Value' => 'The percentage (5 means 5%) or the fixed amount, depending on the Type.',
    'Comm_G_F_Rule_Min' => 'Optional. Sales whose base amount is below this earn nothing from this rule. A sale exactly equal to the threshold does earn.',
    'Comm_G_F_Rule_Cap' => 'Optional. The most this rule can pay on one sale. Works for both percentage and fixed rules.',
    'Comm_G_F_Rule_Applies' => 'All Agents: every agent earns from this rule. Specific Agent: only the agent you select. A Specific Agent rule with no agent selected never pays anyone.',
    'Comm_G_F_Rule_Priority' => 'In a program set to "Only the highest-priority rule pays", the qualifying rule with the highest number wins and the others are skipped. On a tie, a Specific Agent rule beats an All Agents rule. In a program set to "Every matching rule pays", Priority only sets the order.',
    'Comm_G_F_Rule_Active' => 'Untick it to pause this one rule. Commissions it already created are not affected.',
    'Comm_G_T_Stacking' => 'Several rules on one sale',
    'Comm_G_Stacking_Body' => "Each program decides how its rules combine (the \"When several rules match\" setting on the program).\n\nOnly the highest-priority rule pays (the default for new programs): rules are tried from the highest Priority down, and the first one that qualifies for the sale pays. A rule qualifies when the sale reaches its minimum threshold and the result is above 0. This makes tiers easy: \"7% on sales of 10,000 or more\" at priority 10 and \"5%\" at priority 0. To give Sara a special rate, add a Specific Agent rule for her with a higher priority than the All Agents rule.\n\nEvery matching rule pays: all matching rules pay and the amounts add up. An All Agents rule of 3% plus a Specific Agent rule of 2% for Sara gives Sara 5%.\n\nPrograms are separate from each other: every active program pays on its own, so a sale can earn from a base program and a campaign program at the same time.",
    'Comm_G_T_Paying' => 'Paying agents with Commission Receipts',
    'Comm_G_Paying_Body' => "Open Commission Receipts and click Add. Pick the agent: their Approved commissions are listed. Tick the ones you are paying; the Amount fills in with their total, and you can adjust it. The Ref is filled in automatically (CR-000001, CR-000002...), and you can add the payment method, the date and a note.\n\nSaving the receipt marks the ticked commissions as Paid and links them to the receipt. Only Approved commissions can be paid, so approve them first in the Commission Report.\n\nNegative Adjustments (money the agent was overpaid) are listed too. Tick them together with the agent's next commissions so they are taken off that payment.\n\nA receipt is a record of the payout only: it does not create an expense or move money in your accounts. If you track payouts in Expenses or Accounting, record them there as well.",
    'Comm_G_T_Snapshot' => 'When a sale changes',
    'Comm_G_Snapshot_Body' => "Commissions follow the sale. Whenever a sale that has commissions changes, they are recalculated from its current figures: the sale total minus received returns, and the amount paid minus refunds.\n\nUnpaid commissions (Pending or Approved) are simply updated. An Approved commission whose amount changes goes back to Pending so someone checks it again. One that is no longer owed (sale deleted, fully returned, agent changed) is removed.\n\nPaid commissions are never changed. The difference becomes a new Pending row marked Adjustment: positive when more is owed (for example the rest of a Paid Amount sale was paid), negative when the agent was overpaid (for example after a return). Approve it and include it in the agent's next receipt.\n\nEach commission keeps the rule's terms (type, rate, threshold, cap) from when it was first earned. Changing or switching off a rule later does not reprice older sales when they are recalculated.",
    'Comm_G_T_Permissions' => 'Who can do what',
    'Comm_G_Permission' => 'Permission',
    'Comm_G_Lets_You' => 'What it allows',
    'Comm_G_P_View' => 'See all the Commissions pages: programs, agents, rules, receipts, the report and this guide.',
    'Comm_G_P_Add' => 'Create programs, agents and rules, and record Commission Receipts (pay agents).',
    'Comm_G_P_Edit' => 'Edit programs, agents and rules, and approve or cancel commissions in the Commission Report.',
    'Comm_G_P_Delete' => 'Delete programs, agents and rules.',
    'Comm_G_T_Faq' => 'Questions and answers',
    'Comm_G_Q_Empty' => 'I set everything up but the Commission Report is empty.',
    'Comm_G_A_Empty' => 'Check that: the sale was saved after the rule was created; the sale is Completed; the sale has an agent (picked on the sale, or the user who made it is linked to an agent); the program is active and the sale date is inside its dates; the rule is active and applies to that agent; and the sale is at or above the rule\'s minimum threshold. Also check the report\'s date filter: it filters by the date the commission was calculated.',
    'Comm_G_Q_Twice' => 'An agent got two commissions on one sale.',
    'Comm_G_A_Twice' => 'Two rules paid: either the program is set to "Every matching rule pays", or the rules are in two different active programs (every program pays on its own). Set the program to "Only the highest-priority rule pays" if only one should pay. Saving a sale again never duplicates a commission.',
    'Comm_G_Q_Rate' => 'If I change a rule\'s rate, do old commissions change?',
    'Comm_G_A_Rate' => 'No. Each commission keeps the terms of the rule it was earned under, even when its sale is recalculated later. The new rate is used for commissions earned from now on.',
    'Comm_G_Q_Return' => 'The customer returned the goods. What happens to the commission?',
    'Comm_G_A_Return' => 'It is reduced automatically. A received return lowers the sale total and a refund lowers the amount paid. If the commission was not paid yet, it is updated (or removed for a full return). If it was already paid, a negative Adjustment is added and taken off the agent\'s next receipt.',
    'Comm_G_Q_Wrong_Agent' => 'I credited the wrong agent. How do I fix it?',
    'Comm_G_A_Wrong_Agent' => 'Edit the sale, choose the right Sales Agent and save. The commissions move to the right agent. If the first agent had already been paid, a negative Adjustment is added for them.',
    'Comm_G_Q_Inactive' => 'What happens when I deactivate an agent?',
    'Comm_G_A_Inactive' => 'They stop earning on new sales and are hidden from the agent pickers. Their existing commissions stay, can still be approved and paid, and still follow changes to their sales. A sale that was saved with that agent chosen will not fall back to another agent.',
    'Comm_G_Q_Partial' => 'How do Paid Amount rules handle partial payments?',
    'Comm_G_A_Partial' => 'An unpaid sale earns nothing. The commission is created when money is first received (at checkout or when a payment is added) and grows as more payments come in. If part of it was already paid, the rest arrives as a positive Adjustment.',
    'Comm_G_Q_Undo' => 'Can I undo a payment or a cancellation?',
    'Comm_G_A_Undo' => 'A payment, no: Paid is final and receipts cannot be edited or deleted, so check the ticked commissions and the amount before saving. A cancellation, yes: tick the row in the Commission Report and click Recalculate, or save the sale again in Edit Sale.',
    'Comm_G_Q_Dates' => 'Which date do the program dates use?',
    'Comm_G_A_Dates' => 'The sale\'s own date, not the day it was saved. A sale dated last month only uses programs that were valid last month.',
    'Comm_G_When_Changes' => 'Afterwards, any change to a sale that already has commissions updates them on its own: payments edited or deleted, returns and refunds, the status leaving Completed, or the sale being deleted.',
    'Comm_G_F_Program_Mode' => 'What happens when several rules in this program match the same sale. "Only the highest-priority rule pays": rules are tried from the highest Priority down and the first one that qualifies pays. "Every matching rule pays": all of them pay and the amounts add up.',
    'Comm_G_Q_Mode_Old' => 'I set priorities, but rules still add up.',
    'Comm_G_A_Mode_Old' => 'That program is set to "Every matching rule pays". Programs created before this setting existed keep that behaviour so their payouts do not change. Edit the program and choose "Only the highest-priority rule pays".',
    'Comm_G_Q_Negative' => 'Why is there a negative commission?',
    'Comm_G_A_Negative' => 'It is an Adjustment: the agent was paid more than the sale now earns, because of a return, a refund, a lower total, a changed agent or a deleted sale. Approve it and tick it in the agent\'s next receipt so it is deducted.',
    'Comm_Rule_Mode' => 'When several rules match',
    'Comm_Mode_Highest' => 'Only the highest-priority rule pays',
    'Comm_Mode_All' => 'Every matching rule pays (they add up)',
    'Comm_Mode_Highest_Short' => 'Highest priority wins',
    'Comm_Mode_All_Short' => 'Rules add up',
    'Comm_Mode_Highest_Help' => 'Rules are tried from the highest Priority down; the first one that qualifies for the sale pays and the others are skipped. Good for tiers, for example 7% above 10,000 at priority 10 and 5% for everything else at priority 0.',
    'Comm_Mode_All_Help' => 'Every rule that matches the agent pays on the sale, so the amounts add up. Priority only sets the order.',
    'Comm_Priority_Help_Highest' => 'This program pays only the highest-priority rule that qualifies. Give this rule a higher Priority than the rules it should win over. On a tie, a Specific Agent rule beats an All Agents rule.',
    'Comm_Priority_Help_All' => 'This program pays every matching rule, so this rule adds to the others. Priority only sets the order.',
    'Comm_Recalculate' => 'Recalculate',
    'Comm_Recalculate_Help' => 'Works out the ticked rows\' sales again from their current figures, including commissions that were cancelled.',
    'Comm_Adjustment' => 'Adjustment',
    'Comm_Adjustment_Help' => 'A correction to a commission that was already paid, because the sale changed afterwards. A negative amount is taken off the agent\'s next receipt.',
    'Comm_Cancel_Confirm' => 'Cancel the selected commissions?',
    'Comm_Cancel_Confirm_Help' => 'They will not be paid, and stay cancelled when payments or returns come in later. Saving the sale in Edit Sale or clicking Recalculate works them out again.',
    'Fashion_Tiles_Hint' => 'Add your own tiles (image, title and link) to replace the automatic category tiles.',
