    // Restaurant Management — guide page
    'Rst_Guide' => 'Guide',
    'Rst_Guide_Subtitle' => 'Set up the restaurant and learn how a service runs, step by step',
    'Rst_Guide_Module_Off' => 'The Restaurant module is not active for this account',
    'Rst_Guide_Module_Off_Help' => 'It needs the Restaurant feature in your plan and the module switched on in Settings › Modules. Online ordering, QR menus and online booking stay hidden until then.',
    'Rst_Guide_Your_Setup' => 'Your setup',
    'Rst_Guide_Your_Setup_Help' => 'Checked against your own data each time you open this page. Work from the top; the optional steps can come later.',
    'Rst_Guide_Done_N' => '{done} of {total} done',
    'Rst_Guide_Optional' => 'Optional',
    'Rst_Guide_State_Done' => 'Done',
    'Rst_Guide_State_Warn' => 'Needs attention',
    'Rst_Guide_State_Todo' => 'To do',
    'Rst_Guide_Step_Db' => 'Database update',
    'Rst_Guide_Step_Db_Ok' => 'Every restaurant table is in place.',
    'Rst_Guide_Step_Db_Help' => 'Some restaurant tables are missing. Run the latest database update (tenant migrations) and reload this page.',
    'Rst_Guide_Step_Settings' => 'Restaurant settings',
    'Rst_Guide_Step_Settings_Ok' => 'Order types: {types}. A default branch is set.',
    'Rst_Guide_Step_Settings_Help' => 'Choose which order types you take, the branch whose stock restaurant sales use, service charge, tips and rounding.',
    'Rst_Guide_Step_Floor' => 'Dining areas and tables',
    'Rst_Guide_Step_Floor_Ok' => '{areas} areas, {tables} tables.',
    'Rst_Guide_Step_Floor_Help' => 'Add your areas (Indoor, Terrace…) and their tables with the number of seats. "Add several" creates T1–T20 in one go.',
    'Rst_Guide_Step_Stations' => 'Kitchen stations',
    'Rst_Guide_Step_Stations_Ok' => '{n} stations.',
    'Rst_Guide_Step_Stations_Help' => 'Stations (Grill, Fryer, Cold, Desserts, Drinks…) split the kitchen display so each cook sees only their dishes.',
    'Rst_Guide_Step_Dishes' => 'Dishes and add-ons',
    'Rst_Guide_Step_Dishes_Ok' => '{n} dishes set up, {groups} add-on groups.',
    'Rst_Guide_Step_Dishes_Help' => 'Dishes are your normal products. In Restaurant › Menu give them a station, prep time, dietary tags and add-on groups (sizes, extras).',
    'Rst_Guide_Step_Payments' => 'Payments',
    'Rst_Guide_Step_Payments_Ok' => '{n} payment methods ready, with cash, and a default customer for walk-in bills.',
    'Rst_Guide_Step_Payments_Help' => 'Bills need at least one active payment method, a cash method (change is given from cash) and a default customer in System Settings.',
    'Rst_Guide_Step_Staff' => 'Staff permissions',
    'Rst_Guide_Step_Staff_Help' => 'Roles that can take orders: {waiters}, use the kitchen display: {kitchen}, take payments: {cashiers}. Give each role only what that job needs (see "Who does what").',
    'Rst_Guide_Step_First' => 'Your first bill',
    'Rst_Guide_Step_First_Ok' => '{n} bills taken so far.',
    'Rst_Guide_Step_First_Help' => 'Seat a test table on the floor plan, add a dish, send it, mark it ready on the kitchen display and take the payment.',
    'Rst_Guide_Step_Qr' => 'QR table ordering',
    'Rst_Guide_Step_Qr_On' => 'On. {n} tables have a QR code.',
    'Rst_Guide_Step_Qr_Help' => 'Guests scan a code on the table, choose dishes on their phone and send them to the table\'s order. Switch it on in Restaurant Settings, then print the codes.',
    'Rst_Guide_Step_Booking' => 'Online table booking',
    'Rst_Guide_Step_Booking_On' => 'On. Bookings from the online store arrive under Reservations to confirm.',
    'Rst_Guide_Step_Booking_Help' => 'Let guests book a table from the online store. Set the booking hours, step and largest party in Restaurant Settings.',
    'Rst_Guide_Step_Store' => 'Online store and the Restaurant theme',
    'Rst_Guide_Step_Store_On' => 'The Restaurant theme is active. Online orders reach the kitchen: {mode}.',
    'Rst_Guide_Step_Store_Help' => 'In Online Store › Settings choose the "Restaurant" theme: the homepage becomes your menu, with add-ons, pickup / delivery and table booking.',
    'Rst_Guide_How' => 'How it works',
    'Rst_Guide_Service' => 'A service, step by step',
    'Rst_Guide_Service_1_T' => 'Seat',
    'Rst_Guide_Service_1' => 'On the floor plan pick a free table, enter the number of guests and the waiter, then "Seat guests and take the order". A booked party is seated from its booking.',
    'Rst_Guide_Service_2_T' => 'Order',
    'Rst_Guide_Service_2' => 'Tap dishes on the order screen. Choose add-ons, seat and course; add a note for the kitchen. Hold a course to fire it later.',
    'Rst_Guide_Service_3_T' => 'Send',
    'Rst_Guide_Service_3' => '"Send" puts the new dishes on one kitchen ticket. Dishes not sent yet can still be changed or removed; after that they can only be voided with a reason.',
    'Rst_Guide_Service_4_T' => 'Cook',
    'Rst_Guide_Service_4' => 'The kitchen display shows the ticket at each station. Cooks start it, tick dishes as they finish and bump it when everything is ready.',
    'Rst_Guide_Service_5_T' => 'Serve',
    'Rst_Guide_Service_5' => 'Ready dishes show on the floor plan and the order screen. The waiter takes them out and taps "Mark served".',
    'Rst_Guide_Service_6_T' => 'Bill',
    'Rst_Guide_Service_6' => '"Bill & pay" prints the bill and takes the payment: whole bill, split equally or by item. Each payment is a normal POS sale.',
    'Rst_Guide_Service_7_T' => 'Clear',
    'Rst_Guide_Service_7' => 'When everything is paid the order closes and the table turns "Needs cleaning" (or straight to free, per Restaurant Settings).',
    'Rst_Guide_Roles' => 'Who does what',
    'Rst_Guide_Roles_Help' => 'Restaurant permissions are given per role in Group permissions. A user can hold several roles\' worth of permissions.',
    'Rst_Guide_Job' => 'Job',
    'Rst_Guide_Give' => 'Give these permissions',
    'Rst_Guide_Job_Waiter' => 'Waiter',
    'Rst_Guide_Job_Cook' => 'Cook',
    'Rst_Guide_Job_Cashier' => 'Cashier',
    'Rst_Guide_Job_Host' => 'Host / front desk',
    'Rst_Guide_Job_Supervisor' => 'Supervisor',
    'Rst_Guide_Job_Manager' => 'Manager',
    'Rst_Guide_Menu' => 'Menu, stations and add-ons',
    'Rst_Guide_Menu_1' => 'Every product you sell can be a dish. Restaurant › Menu (or the "Dish details" card on the product form) adds the restaurant information.',
    'Rst_Guide_Menu_2' => 'Add-on groups hold choices with a price: "Size" (choose 1) or "Extras" (up to 3). The rules are checked on every order, also online.',
    'Rst_Guide_Menu_3' => 'An add-on can use up an ingredient: link "Extra cheese" to your Cheese product and each one takes that stock.',
    'Rst_Guide_Menu_4' => 'Mark a dish sold out for today with one switch; it comes back tomorrow by itself. Meal times (breakfast, lunch, dinner) limit when a dish is offered.',
    'Rst_Guide_Menu_5' => 'A recipe is a combo product: with virtual combo stock on, selling the dish takes its components from stock.',
    'Rst_Guide_Kitchen' => 'Kitchen display',
    'Rst_Guide_Kitchen_1' => 'Open Restaurant › Kitchen on a screen in the kitchen. Pick the station; dishes without a station show on every station.',
    'Rst_Guide_Kitchen_2' => 'Tickets turn amber and then red as they wait (Restaurant Settings › late after N minutes). A beep announces new tickets.',
    'Rst_Guide_Kitchen_3' => 'Start → tick dishes → Bump. "Done at this station" finishes only this station\'s dishes on a shared ticket.',
    'Rst_Guide_Kitchen_4' => 'Served tickets stay 15 minutes so a mistake can be recalled. Tickets can be printed on an 80 mm printer.',
    'Rst_Guide_Kitchen_5' => 'Orders from the online store and from table QR codes are marked "Online" or "QR" on their ticket.',
    'Rst_Guide_Bills' => 'Bills and payments',
    'Rst_Guide_Bills_1' => 'Every payment is a normal POS sale: stock, the cash register, accounting, loyalty points and e-invoicing work as at the POS.',
    'Rst_Guide_Bills_2' => 'Service charge is a percentage of the dishes before tax, for dine-in (or every order, per your setting). Tips are a preset percentage or an amount.',
    'Rst_Guide_Bills_3' => 'A discount needs the "Restaurant discounts" permission and is capped by the largest discount in Restaurant Settings.',
    'Rst_Guide_Bills_4' => 'Rounding goes down to your step, in the guest\'s favour, on the payment that settles the bill.',
    'Rst_Guide_Bills_5' => 'Split equally: one sale, one payment line per person (shares to the cent). Split by item: each guest\'s dishes become their own sale; pick a seat to select its dishes.',
    'Rst_Guide_Bills_6' => 'If the bill changed after it was shown (a dish added from a QR code, a tip changed), the payment is refused so the guest is never charged for something they did not see.',
    'Rst_Guide_Bills_7' => 'Paid dishes cannot be voided. If the unpaid rest of an order is voided, the order closes as paid and the table can be cleared.',
    'Rst_Guide_Bookings' => 'Reservations and waitlist',
    'Rst_Guide_Bookings_1' => 'Bookings hold a table for their length (default in Restaurant Settings). Two bookings can never overlap on a table.',
    'Rst_Guide_Bookings_2' => 'The floor plan shows each table\'s next booking and warns when it is due soon; "They\'re here — seat" seats the party.',
    'Rst_Guide_Bookings_3' => 'After the no-show time a late party can be marked as a no-show; a mistake can be restored.',
    'Rst_Guide_Bookings_4' => 'The waitlist keeps walk-ins in order with their quoted wait. Call or WhatsApp them when a table is ready, then seat them.',
    'Rst_Guide_Bookings_5' => 'Online bookings arrive as "Booked" (a sidebar badge counts them) for you to confirm.',
    'Rst_Guide_Online' => 'Online orders, QR menus and online booking',
    'Rst_Guide_Online_1' => 'With the Restaurant store theme the online store homepage is your menu, with add-ons and dietary filters; shoppers pay at checkout as usual.',
    'Rst_Guide_Online_2' => '"Online orders to the kitchen" decides when they reach the kitchen display: when placed (paid, or a signed-in customer paying on delivery / pickup), when accepted, or never.',
    'Rst_Guide_Online_3' => 'Table QR codes (Floor setup › Table QR codes) open the menu for that table. "New link" retires a printed code.',
    'Rst_Guide_Online_4' => 'QR orders wait on the table\'s order for a waiter to send them, unless "Send QR orders straight to the kitchen" is on. Guests pay with staff.',
    'Rst_Guide_Online_5' => 'Online booking only offers times when a table that fits the party is free for the whole booking, and limits each phone number to 3 upcoming bookings.',
    'Rst_Guide_Online_6' => 'All of this is part of the online store: it must be switched on and included in your plan.',
    'Rst_Guide_Reports' => 'Dashboard and reports',
    'Rst_Guide_Reports_1' => 'The dashboard shows today against the same day last week: sales, bills, guests, average bill, voids and discounts, plus what is happening right now.',
    'Rst_Guide_Reports_2' => 'Sales are restaurant bills plus online orders that reached the kitchen. Dish sales and margins are before tax, using each product\'s cost.',
    'Rst_Guide_Reports_3' => 'Reports: sales by day and payment method, dishes, voids and cancellations (with reasons), staff, kitchen times and reservations — each exports to Excel.',
    'Rst_Guide_Reports_4' => 'Staff limited to some branches only see their branches; orders without a branch are shared by all.',
    'Rst_Guide_Faq' => 'Good to know',
    'Rst_Guide_Faq_1_Q' => 'A takeaway was paid before I pressed "Send". Will it be cooked?',
    'Rst_Guide_Faq_1_A' => 'Yes. Paying sends any dishes that were not sent yet to the kitchen.',
    'Rst_Guide_Faq_2_Q' => 'Why can\'t I clear a table?',
    'Rst_Guide_Faq_2_A' => 'Its order still has unpaid dishes. Take the payment, void what was not eaten, or cancel the order (only when nothing is paid yet).',
    'Rst_Guide_Faq_3_Q' => 'Two tables were pushed together. What happens to their orders?',
    'Rst_Guide_Faq_3_A' => '"Join tables" moves the second table\'s dishes (and any payments) onto the main table\'s order; "Unjoin" splits the tables again.',
    'Rst_Guide_Faq_4_Q' => 'Can card payments use Stripe here?',
    'Rst_Guide_Faq_4_A' => 'No. Stripe card payments need the POS card form; for a card terminal add a payment method such as "Card" and use that on the bill.',
    'Rst_Guide_Faq_5_Q' => 'A dish is out of stock in one branch only.',
    'Rst_Guide_Faq_5_A' => 'Stock is taken from the order\'s branch (the table\'s area, else the default branch in Restaurant Settings). Use "Sold out today" to stop orders quickly.',
    'Rst_Guide_Faq_6_Q' => 'Do I need a printer?',
    'Rst_Guide_Faq_6_A' => 'No. Bills, receipts and kitchen tickets print from the browser on any printer; 80 mm receipt printers fit best.',
    'Rst_Guide_Faq_7_Q' => 'Where do the restaurant menus come from in the online store?',
    'Rst_Guide_Faq_7_A' => 'From the same products, categories and add-ons. Products hidden from the online store, and categories not shown in the store, stay off the online menu and the QR menu.',
