    'Bkm_Guide_Customers_1' => 'A website booking is added to your customers; someone booking again with the same email and phone is matched.',
    'Bkm_Guide_Customers_2' => 'With the CRM on your plan, bookings can be noted on the customer or their lead, and requests can open a deal.',
