    'Bkm_Guide_Job_Owner' => 'Owner or accountant',
    'Bkm_Guide_Faq' => 'Questions',
    'Bkm_Guide_Faq_1_Q' => 'Why does a service not show on the website?',
    'Bkm_Guide_Faq_1_A' => 'It needs booking details (Services), "Show on website" on, the product active, and — to pick a time — someone bookable online who does it.',
    'Bkm_Guide_Faq_2_Q' => 'Why are there no free times?',
    'Bkm_Guide_Faq_2_A' => 'Check the staff\'s working hours, days off, holidays and approved leave, the notice time and how many days ahead customers can book.',
    'Bkm_Guide_Faq_3_Q' => 'Can two customers take the same time?',
    'Bkm_Guide_Faq_3_A' => 'No. The time is checked again when they book, and a held or confirmed booking blocks it. Classes share seats up to their limit.',
    'Bkm_Guide_Faq_4_Q' => 'What happens when a hold runs out?',
    'Bkm_Guide_Faq_4_A' => 'The time is free again for others. The booking stays in Requests until you answer it (or is cancelled if its deposit was not paid).',
    'Bkm_Guide_Faq_5_Q' => 'Do customers need an account?',
