    'Mkg_Guide_Flow' => 'Sending a campaign',
    'Mkg_Guide_Flow_1_T' => 'Set up a channel',
    'Mkg_Guide_Flow_1' => 'turn on Email, SMS or WhatsApp in Marketing Settings and connect its server or gateway.',
    'Mkg_Guide_Flow_2_T' => 'Pick the audience',
