    'Mkg_Guide_Audience' => 'Who receives it',
    'Mkg_Guide_Audience_1' => 'All customers sends to every customer that has not been deleted.',
    'Mkg_Guide_Audience_2' => 'A segment filters customers by city, last purchase date, number of purchases and total spent. Preview shows how many match before you save.',
    'Mkg_Guide_Audience_3' => 'The list is fixed when you click send. Customers added later are not included.',
    'Mkg_Guide_Audience_4' => 'Customers without an email address (Email) or phone number (SMS, WhatsApp) stay on the list as Skipped.',
    'Mkg_Guide_Audience_5' => 'Sending a failed campaign again rebuilds the list from the segment and retries everyone.',
    'Mkg_Guide_Audience_Leads' => 'With the CRM on, a segment can target CRM leads instead of customers (tags, source, status, score and more). Leads who unsubscribed are skipped, and emails to leads always carry an unsubscribe link.',
    'Mkg_Guide_Channels' => 'Channels',
    'Mkg_Guide_Ch_email_1' => 'Sent through your own mail server (Settings > Mail Settings). The platform mailer is never used.',
