    'Mkg_Guide_Ch_email_3' => 'Add a subject and an optional attachment. The message can contain HTML.',
    'Mkg_Guide_Ch_email_4' => 'Customers without an email address are skipped.',
    'Mkg_Guide_Ch_sms_1' => 'Works with any HTTP SMS gateway: enter its API URL, key, sender ID, method and the field names it expects.',
    'Mkg_Guide_Ch_sms_2' => 'One SMS goes to each customer with a phone number; the rest are skipped.',
    'Mkg_Guide_Ch_sms_3' => 'Your gateway charges for every message, so test on a small segment first.',
    'Mkg_Guide_Ch_whatsapp_1' => 'Connect a WhatsApp HTTP gateway, or the Meta WhatsApp Cloud API (graph.facebook.com).',
    'Mkg_Guide_Ch_whatsapp_2' => 'More than 24 hours after a customer last wrote to you, WhatsApp only delivers Meta-approved templates.',
