    'Mkg_Guide_Faq' => 'Common questions',
    'Mkg_Guide_Faq_1_Q' => 'My campaign stays on Sending and nothing goes out.',
    'Mkg_Guide_Faq_1_A' => 'The background sender has not picked it up. After 30 minutes without progress the Send Now button comes back: click it to resume. If it keeps happening, ask your platform administrator to check that background jobs (the queue worker) are running.',
    'Mkg_Guide_Faq_2_Q' => 'Recipients show "Skipped: Email channel disabled".',
    'Mkg_Guide_Faq_2_A' => 'Turn on Enable Email in Marketing Settings, then send the campaign again.',
    'Mkg_Guide_Faq_3_Q' => 'Recipients show "No mail server configured".',
    'Mkg_Guide_Faq_3_A' => 'Email campaigns only go through your own mail server. Add it in Settings > Mail Settings.',
    'Mkg_Guide_Faq_4_Q' => 'Fewer people got the message than are in my segment.',
    'Mkg_Guide_Faq_4_A' => 'Customers without an email address (Email) or phone number (SMS, WhatsApp) are skipped. Open the campaign to see who was skipped and why.',
    'Mkg_Guide_Faq_5_Q' => 'Does Sent mean the customer received it?',
    'Mkg_Guide_Faq_5_A' => 'Sent means your mail server or gateway accepted the message. Inbox delivery, opens and spam filtering are not tracked.',
    'Mkg_Guide_Faq_6_Q' => 'Can I edit a campaign after sending it?',
    'Mkg_Guide_Faq_6_A' => 'No. Sending and sent campaigns are locked; create a new campaign instead.',
    'Mkg_Guide_Faq_7_Q' => 'My WhatsApp messages are not arriving.',
    'Mkg_Guide_Faq_7_A' => 'More than 24 hours after a customer last wrote to you, WhatsApp only delivers Meta-approved templates. Use the WhatsApp Cloud API and choose an approved template in the campaign.',
    'Mkg_Guide_Faq_8_Q' => 'If I send a campaign again, will customers get it twice?',
    'Mkg_Guide_Faq_8_A' => 'Resuming a stuck campaign only sends to recipients still pending, so nobody already reached is messaged again. Sending a failed campaign again starts over with a fresh list.',

