    'Pd_Guide_How_Title' => 'How it works',
    'Pd_Guide_How_Intro' => 'A POS device is a card terminal or fiscal cash register next to the till. The POS sends it the amount, waits for the customer to pay, and records the payment only after the device approves it.',
    'Pd_Guide_Step_1' => 'Add the device here: model, warehouse, and the payment method its card payments are recorded as (for example "Credit Card").',
    'Pd_Guide_Step_2' => 'Choose how the POS reaches it: a local bridge on the cashier computer, or your provider\'s cloud API. Enter the IDs and keys from your bank or provider.',
    'Pd_Guide_Step_3' => 'Press Test connection. Bridge devices must be tested from the cashier computer the bridge runs on.',
    'Pd_Guide_Step_4' => 'On the POS, pick that payment method, press "Charge on device" and let the customer pay. The sale can be completed once the device approves.',
    'Pd_Guide_Step_5' => 'Check Transactions for card payments taken without a sale (for example, a checkout that was abandoned) and void or refund them.',
    'Pd_Guide_Bridge_Text' => 'For devices driven by a vendor SDK on the cashier PC (USB, serial or LAN pairing). The browser cannot use the SDK directly, so a small bridge program wraps it and listens on this computer.',
    'Pd_Guide_Bridge_Point_1' => 'The POS sends each request to the bridge URL from the cashier\'s browser; the POS server never needs to reach your shop network.',
    'Pd_Guide_Bridge_Point_2' => 'Requests and answers are signed with the shared secret, so an approval cannot be faked from the browser.',
    'Pd_Guide_Bridge_Point_3' => 'Install and start the bridge on every computer that takes card payments on this device.',
    'Pd_Guide_Cloud_Text' => 'For providers that reach the device over the internet. The POS server calls the API, so nothing has to be installed on the cashier computer.',
    'Pd_Guide_Cloud_Point_1' => 'The API URL must be https:// on a public address.',
    'Pd_Guide_Cloud_Point_2' => 'While the customer pays, the POS asks for the status every 2 seconds, so the status endpoint should know the payment by its reference; if the API answers before the card is done ("pending"), the polling decides.',
    'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
    'Pd_Guide_Ide280_Text' => 'The IDE280 is a new-generation fiscal cash register (YN ÖKC) with a card reader. It is normally integrated through Ingenico\'s ECR / GMP3 SDK, or through your bank\'s integration service.',
    'Pd_Guide_Ide280_Point_1' => 'Pair the device with the cashier computer as described in the Ingenico / bank documentation, then point the bridge (or the API settings) at it.',
    'Pd_Guide_Ide280_Point_2' => 'Amounts are sent both as decimals and in kuruş (amount_minor), with currency TRY / 949.',
    'Pd_Guide_Ide280_Point_3' => 'With "Full fiscal receipt", each item carries the device department of its VAT rate — match the VAT departments to how the device is programmed.',
    'Pd_Guide_Protocol_Title' => 'Bridge / API contract',
