'Oc_Download_Connector_3' => 'Download for OpenCart 3',
'Oc_Opencart3_Title' => 'OpenCart 3 stores',
'Oc_Opencart3_Desc' => 'OpenCart 3 has no variants of its own, only options. A product with one option (Size, say) is synced with stock per option value, which maps to the variants here. A product with several options gets its options created without stock per combination: its stock is kept on the product as a whole, and its sales lines come in against the product.',
'Oc_G_Title' => 'OpenCart Guide',
'Oc_G_Open_Settings' => 'Open OpenCart settings',
'Oc_G_Your_Setup' => 'Your setup',
'Oc_G_Your_Setup_Help' => 'Where this workspace stands. The steps update as you go.',
'Oc_G_Step_Install' => 'Install the {company} Connector on your store',
'Oc_G_Step_Install_Help' => 'A small extension that gives {company} access to products, stock and orders. OpenCart has no API for those on its own.',
'Oc_G_Step_Connect' => 'Connect the store',
'Oc_G_Step_Connect_Help' => 'Paste the store URL and the secret from the module page on the Connection tab, save, then run Test Connection.',
'Oc_G_Step_Connect_Done' => 'Connected: connector {connector} on OpenCart {opencart}.',
'Oc_G_Step_Enable' => 'Switch the sync on',
'Oc_G_Step_Enable_Help' => 'Nothing moves while the integration is disabled; webhooks from the store are acknowledged and ignored.',
'Oc_G_Step_Products' => 'Link the products',
'Oc_G_Step_Products_Help' => 'Pull the store\'s catalogue or push yours, so every product on both sides is linked before stock starts flowing.',
'Oc_G_Step_Products_Done' => '{n} products and {v} variants linked.',
'Oc_G_Step_Orders' => 'Receive orders',
'Oc_G_Step_Orders_Help' => 'Once connected, new orders arrive by themselves. Place a test order in the store to see it appear under Sales.',
'Oc_G_Step_Orders_No_Webhook' => 'Orders were imported, but none has arrived through the store\'s notice yet. If the store cannot reach this address, orders still arrive by the check every few minutes.',
'Oc_G_Step_Orders_Done' => 'The store is sending order notices.',
'Oc_G_Install_Title' => 'Install the connector',
'Oc_G_Install_Intro' => 'Pick your OpenCart version. The connector is installed through OpenCart\'s own extension installer; no files are edited by hand.',
'Oc_G_Opencart_4' => 'OpenCart 4.x',
'Oc_G_Opencart_3' => 'OpenCart 3.x',
'Oc_G_I4_1' => 'Download the connector for OpenCart 4.',
'Oc_G_I4_2' => 'In your OpenCart admin, open {path}, upload the file and click Install next to it.',
'Oc_G_I4_3' => 'Open {path}, find {name} and click Install, then Edit.',
'Oc_G_I3_1' => 'Download the connector for OpenCart 3.',
'Oc_G_I3_2' => 'In your OpenCart admin, open {path}, upload the file and wait for the steps to finish.',
'Oc_G_I3_3' => 'Open {path}, find {name} and click Install, then Edit.',
'Oc_G_I_4' => 'The module page shows the store URL and a secret. Copy both.',
'Oc_G_I_5' => 'Back here, paste them on the Connection tab, save, and run {test}. This also tells the store where to send order notices.',
'Oc_G_Requirements' => 'What the store needs',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 or 4.0 and up, PHP with cURL (standard on any host), and a store address reachable from the internet. If the store is on a private network, orders still arrive through the check that runs every few minutes, as long as this workspace can reach the store.',
'Oc_G_First_Title' => 'The first sync',
'Oc_G_First_Shop_Has' => 'The store already has the catalogue',
'Oc_G_First_Shop_Has_Text' => 'Pull products on the Products tab. Products are matched by model or SKU to your product codes and created when missing; tick the stock option to take the store\'s quantities as opening stock.',
'Oc_G_First_Company_Has' => '{company} has the catalogue',
'Oc_G_First_Company_Has_Text' => 'Push products. Missing products are created in the store with their stock; existing ones are linked by model or SKU and updated.',
'Oc_G_First_Both' => 'Both sides have products',
'Oc_G_First_Both_Text' => 'Pull first, so existing store products get linked instead of duplicated, then push to create what the store lacks. Keep product codes and models the same on both sides.',
'Oc_G_Stock_Master' => '{company} holds the stock figure',
'Oc_G_Stock_Master_Desc' => 'After the first sync, the quantity in the store is always written from {company}. Editing a quantity in OpenCart has no lasting effect: the next movement or the hourly check overwrites it.',
'Oc_G_How_Title' => 'How it works',
'Oc_G_T_Products' => 'Products',
'Oc_G_Products_1' => 'A product is matched by its code here against the model and SKU in the store. The link is remembered, so renaming a product afterwards does not break it.',
'Oc_G_Products_2' => 'When {company} pushes a product it sets the model, SKU, name, price, status and stock. The description, image and category are only written when the product is new in the store or has none, so copy written in OpenCart stays.',
'Oc_G_Products_3' => 'A product hidden from the online store or not for sale here is not created in the store; one already linked is set to disabled there instead.',
'Oc_G_T_Variants' => 'Variants and options',
'Oc_G_Variants_4' => 'OpenCart 4 has real variants (a product with Color and Size choices), each with its own stock. They map to your variants both ways, and each is matched by its own model.',
'Oc_G_Variants_3' => 'OpenCart 3 has no variants, only options, and stock per option value. A product with one option (Size, say) is synced with stock per value, which maps to your variants. A product with several options gets its options created without stock per combination: its stock stays on the product as a whole, and its sales lines come in against the product.',
'Oc_G_Variants_Multi' => 'A store product that only has options, with no variants created, is imported as one product; this is noted in the logs.',
'Oc_G_T_Stock' => 'Stock',
'Oc_G_Stock_1' => 'With the stock switch on, every movement here (a sale, a return, a purchase, an adjustment, a transfer) updates the store within seconds, after the page has answered, so the cashier never waits on the store.',
'Oc_G_Stock_2' => 'Once an hour every linked product is checked and corrected, which covers bulk changes the live push cannot see. The Stock tab pushes everything on demand.',
'Oc_G_Stock_3' => 'Services, products marked always in stock, and combos whose components are unlimited are shown as always available in the store. Pick a warehouse on the Connection tab to count only that warehouse; otherwise all warehouses are added up.',
'Oc_G_T_Orders' => 'Orders and statuses',
'Oc_G_Orders_1' => 'A new or changed order is announced by the store at once and read back over the signed connection, so nothing in the notice itself is trusted. Every few minutes a check pulls anything a notice missed. Each order becomes one sale with reference OC-<order number>; the customer is matched by email or created.',
'Oc_G_Col_List' => 'Status list',
'Oc_G_Col_Meaning' => 'What it does here',
'Oc_G_Col_Default' => 'Set from your store',
'Oc_G_Default_Commit' => 'The statuses that subtract stock in OpenCart (Pending, Processing, Shipped, Complete by default)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'The lists are filled from your store on the first connection and can be changed on the Connection tab. Keep the first list the same as the statuses that subtract stock in OpenCart, so both sides move stock on the same step.',
'Oc_G_Orders_3' => 'An order with an item that matches no product is held, and the product is imported from the store if it exists there. Held orders are tried again on each scheduled check; after twelve tries they are logged and left for you to pull by hand.',
'Oc_G_T_Cancel' => 'Cancellations and refunds',
'Oc_G_Cancel_1' => 'When an order reaches a cancelled status in the store, its sale here is reversed: stock comes back, its payments are removed and the sale is deleted, exactly as deleting it on the Sales page would do.',
'Oc_G_Cancel_2' => 'A sale already delivered, with a return, or accepted by a tax authority is never reversed by the store. It is flagged in its notes and in the logs for you to review.',
'Oc_G_Cancel_3' => 'If the order is reinstated in the store afterwards, it comes in again as a new sale.',
'Oc_G_T_Automation' => 'Automation switches',
'Oc_G_Auto_1' => 'Import orders automatically: order notices and the scheduled check. Off, orders only arrive when you pull them on the Orders tab.',
'Oc_G_Auto_2' => 'Push stock automatically: live stock updates and the hourly check. Off, the store only changes when you push stock by hand.',
'Oc_G_Auto_3' => 'Push product changes automatically: a product created or edited here updates the store right away. Off, use the Products tab.',
'Oc_G_T_Faq' => 'Questions',
'Oc_G_Q_Secret' => 'Test Connection says the secret does not match',
'Oc_G_A_Secret' => 'Open the {company} Connector module in OpenCart and copy the secret again; a reinstalled module gets a new one. Paste it on the Connection tab and save before testing.',
'Oc_G_Q_Clock' => 'Test Connection says the store clock is too far off',
'Oc_G_A_Clock' => 'Signed requests carry the time and are refused when the two clocks differ by more than five minutes. Set the date and time on the store\'s server.',
'Oc_G_Q_Redirect' => 'Test Connection says the store redirects to another address',
'Oc_G_A_Redirect' => 'Your store answers at a different address, usually https instead of http or with www. Use the address shown in the message as the store URL.',
'Oc_G_Q_Not_Answering' => 'Test Connection says the connector did not answer',
'Oc_G_A_Not_Answering' => 'The address is not an OpenCart store, or the module is not installed or is disabled. Check the store URL, then that the {company} Connector shows as installed and enabled under Extensions → Modules.',
'Oc_G_Q_No_Orders' => 'Orders are placed in the store but take minutes to appear',
'Oc_G_A_No_Orders' => 'The store cannot reach this workspace, so orders only arrive through the scheduled check. Look at the {company} address on the module page: it must be reachable from the store\'s server. Running Test Connection registers it again.',
'Oc_G_Q_Stock_Wrong' => 'A quantity in the store is wrong',
'Oc_G_A_Stock_Wrong' => 'Push stock on the Stock tab, which rewrites every linked product from the figures here. If it keeps drifting, check that the stock switch is on and that no one is editing quantities in OpenCart.',
'Oc_G_Q_Out_Of_Stock' => 'A product shows out of stock in the store although there is stock here',
'Oc_G_A_Out_Of_Stock' => 'On OpenCart 3 a product with several options keeps its stock on the product as a whole; check the product\'s quantity in the store rather than its options. For any product, push stock once and look at the logs for that product.',
'Oc_G_Q_Held' => 'The logs say an order was held',
'Oc_G_A_Held' => 'One of its items matches no product here and could not be imported from the store, usually because the product was deleted there. Create or link the product, then pull orders on the Orders tab.',
'Oc_G_Q_Deleted_Sale' => 'I deleted an imported sale and it came back',
'Oc_G_A_Deleted_Sale' => 'While the order is live in the store, the next notice or check imports it again. Cancel the order in the store instead, which reverses the sale here.',
'Oc_G_Q_Uninstall' => 'How do I disconnect the store?',
'Oc_G_A_Uninstall' => 'Switch the sync off on the Connection tab; nothing moves while it is off. To remove the integration from the store, uninstall the {company} Connector under Extensions → Modules.',
'Oc_Full_Guide' => 'Open the full guide',
'Comm_Receipt_Account_Hint' => 'The cash or bank account this payout leaves. Its balance drops by the amount and the ledger posts Sales Commission Expense against it.',
'Comm_G_Q_Ledger' => 'What does a commission payout do in the accounts?',
'Comm_G_A_Ledger' => 'When you create a receipt and pick an account, that account balance drops by the receipt amount and, if automatic journals are on, a journal is posted: debit Sales Commission Expense (5200-COMM), credit the chosen cash or bank account. With no account selected the credit falls to the default Cash account and no balance changes.',
'Hide_Zero_Decimals' => 'Hide Zero Decimals',
'Sys_Hide_Zero_Decimals_Help' => 'Show whole-number amounts without their decimals: 100.00 becomes 100, while 100.50 keeps its decimals. Display only; stored values and calculations are unchanged.',
'Sys_Currency_Position_Before_NoSpace' => 'Before the amount, no space',
'Sys_Currency_Position_After_NoSpace' => 'After the amount, no space',
'Supplier_Wallet' => 'Supplier Wallet',
'Supplier_Wallets' => 'Supplier Wallets',
'Supplier_Ledger' => 'Supplier Ledger',
'Sys_Supplier_Wallet_Help' => 'Hold prepaid balances with suppliers: top-ups, return credits, and pay purchases from the wallet. Needs the Supplier Wallet plan feature.',
'SW_Allow_Negative' => 'Allow negative wallet balance',
'Sys_SW_Allow_Negative_Help' => 'Let a purchase payment overdraw the supplier wallet instead of being refused.',
'SW_Wallet_Balance' => 'Wallet Balance',
'SW_Net_After_Wallet' => 'Net After Wallet',
'SW_Balance_After' => 'Balance After',
'SW_Balances' => 'Balances',
