'SW_Freeze' => 'Freeze Wallet',
'SW_Unfreeze' => 'Unfreeze Wallet',
'SW_Freeze_Confirm' => 'A frozen wallet refuses every move until it is unfrozen. Continue?',
'SW_Unfreeze_Confirm' => 'Allow wallet moves for this supplier again?',
'SW_Only_With_Balance' => 'Only wallets with a balance',
'SW_Top_Up' => 'Top Up',
'SW_Refund' => 'Refund from Wallet',
'SW_Adjust' => 'Adjust Balance',
'SW_Top_Up_Help' => 'Money paid to the supplier in advance. It leaves the chosen account and is kept in the wallet until it is spent on purchases.',
'SW_Refund_Help' => 'The supplier returns part of the advance in cash. The amount leaves the wallet and lands in the chosen account.',
'SW_Adjust_Help' => 'Manual correction with no cash movement. A reason is required and is kept in the ledger.',
'SW_Adjust_Credit' => 'Add to wallet',
'SW_Adjust_Debit' => 'Deduct from wallet',
'SW_Pay_From_Wallet' => 'Pay from supplier wallet',
'SW_Pay_From_Wallet_Help' => 'The amount is taken from the prepaid balance held with this supplier. No account or payment method is needed.',
'SW_Credit_To_Wallet' => 'Credit to supplier wallet',
'SW_Credit_To_Wallet_Help' => 'Instead of cash, the supplier settles this return as wallet credit you can spend on later purchases.',
'SW_Disabled_Hint' => 'Supplier Wallet is switched off. Turn it on under System Settings > Features (it also needs the Supplier Wallet plan feature).',
'SW_Src_top_up' => 'Top-up',
'SW_Src_refund' => 'Refund',
'SW_Src_adjustment' => 'Adjustment',
