'SW_Src_reversal' => 'Reversal',
'SW_Err_wallet_disabled' => 'Supplier wallet is not enabled.',
'SW_Err_wallet_frozen' => 'This supplier wallet is frozen.',
'SW_Err_wallet_insufficient_balance' => 'Insufficient wallet balance.',
'SW_Err_wallet_invalid_amount' => 'Amount must be greater than zero.',
'SW_Perm_View' => 'Supplier wallet: view',
'SW_Perm_Manage' => 'Supplier wallet: manage',
'SW_Top_Ups_Total' => 'Top-ups (Total)',
'SW_Spent_Total' => 'Spent from Wallet',
'Purchases_Grand' => 'Purchases (Grand)',
'Purchases_Paid' => 'Purchases (Paid)',
'Purchases_Due' => 'Purchases (Due)',
'Purchase_Update_Selling_Price' => 'Edit Selling Price on Purchase',
'Sys_Purchase_Update_Selling_Price_Help' => 'Adds a selling price field to every purchase line, next to the cost. A price typed there replaces the product\'s selling price when the purchase is saved; leave it blank to keep the current price.',
'Current_Selling_Price' => 'Current selling price',
'Keep_Current_Price' => 'Leave blank to keep the current price',
'Selling_Price_In_Base_Currency' => 'Entered in the base currency',
'Purchase_Update_Product_Cost' => 'Update Product Cost on Purchase',
'Sys_Purchase_Update_Product_Cost_Help' => 'When a received purchase is saved, each product\'s cost becomes the net unit cost on its purchase line (after the line discount, tax excluded, per base unit). Pending and ordered purchases do not change it.',
'Show_Stock_In_Search_Results' => 'Show Stock in Search Results',
'Show_Stock_In_Search_Results_Help' => 'Show each product\'s available quantity next to it in the POS search dropdown.',
'Layout_6_Tabular' => 'Layout 6 - Tabular',
'Show_Signature_Line' => 'Show Signature Line',
'Show_Signature_Line_Desc' => 'Prints a blank customer signature line under the receipt, whatever layout is selected.',
'Customer_Signature' => 'Customer signature',
'Set_Signature_Label' => 'Signature line label (blank = "Customer signature")',
'Oc_Code_Source' => 'Product code source',
'Oc_Code_Source_Help' => 'Which OpenCart field is the product code here. Model is required in OpenCart, so some stores type a category or product type into it and keep the real article code in SKU, ISBN, UPC, EAN, JAN or MPN; choose that field for such a store. The model, then the SKU, are used when the chosen field is blank. Applies to pulled products, matching and pushes.',
'Oc_Code_Source_Model' => 'Model (default)',
'Oc_Code_Source_Sku' => 'SKU',
'Oc_Connector_Link' => 'Connector website',
'Oc_Connector_Link_Help' => 'Your website address. OpenCart links the connector name to it on the Extensions > Installer page. Leave blank to use this {company} workspace address.',
'Store_Warehouses_Help' => 'Stock shown and deducted online comes from these warehouses. While "Restrict products by warehouse" is on in Features, the shop also lists only the products that belong to (or hold stock in) these warehouses.',
'Oc_Code_Source_Needs_Update' => 'The connector installed in the store (version {version}) only reports the Model and SKU. Download the connector again and upload it over the old one in the store for this field to be read.',
'Oc_L_Title' => 'OpenCart Logs',
'Oc_L_Intro' => 'Every product pull, push, stock update, order and store call is recorded here. Filter to errors to see what failed, open a row to read what it means and what to do, and export the list when you need to send it to support.',
'Oc_L_Tab_Hint' => 'The full logs page explains each entry, filters by action and date, and exports to a file.',
'Oc_L_Open_Page' => 'Open the logs page',
'Oc_L_Entries' => 'Entries',
