'Oc_L_Col_Action' => 'Action',
'Oc_L_Col_Message' => 'What happened',
'Oc_L_Open_Row' => 'Click a row for the details and what to do.',
'Oc_L_What_It_Means' => 'What this means',
'Oc_L_What_To_Do' => 'What to do',
'Oc_L_Details' => 'Details',
'Oc_L_Raw' => 'Raw data',
'Oc_L_Support' => 'Still stuck? Export the logs and send the file to support with a note of what you were doing.',
'Oc_L_D_Errors' => 'Items that failed',
'Oc_L_D_Warnings' => 'Warnings from the store',
'Oc_L_D_Codes_Suffixed' => 'Codes already used by another store product (created here as code-id)',
'Oc_L_D_Options' => 'Products with options but no variants (stock is kept per product)',
'Oc_L_D_Unmatched' => 'Order items that match no product here',
'Oc_L_D_Store_Total' => 'Products in the store',
'Oc_L_D_Per_Page' => 'Products per page',
'Oc_L_D_Order' => 'OpenCart order',
'Oc_L_D_Sale' => 'Sale',
'Oc_L_D_Product_Ids' => 'Products queued',
'Oc_L_D_Stock_Ids' => 'Stock changes queued',
'Oc_L_D_Id' => 'ID',
'Oc_L_D_Error' => 'Error',
'Oc_L_Act_products_pull' => 'Products pull',
'Oc_L_Act_products_push' => 'Products push',
'Oc_L_Act_inventory_push' => 'Stock push',
'Oc_L_Act_orders_pull' => 'Orders pull',
'Oc_L_Act_orders_catch_up' => 'Scheduled orders pull',
'Oc_L_Act_orders_import' => 'Order import',
'Oc_L_Act_orders_retry' => 'Order retry',
'Oc_L_Act_orders_reverse' => 'Order cancelled',
'Oc_L_Act_orders_review' => 'Order needs review',
'Oc_L_Act_webhook_order' => 'Order notification',
'Oc_L_Act_auto_sync' => 'Auto-sync',
'Oc_L_Act_connect_test' => 'Test connection',
'Oc_L_Act_scheduled' => 'Scheduled sync',
'Oc_L_Act_sync' => 'Sync',
'Oc_L_H_Secret' => 'The secret saved here is not the one the connector module in OpenCart has, so the store rejects every call.',
'Oc_L_F_Secret' => 'In OpenCart open Extensions → Modules → the connector, copy the secret shown there, paste it on the Connection tab and save. Reinstalling the module creates a new secret.',
'Oc_L_H_Clock' => 'The OpenCart server clock differs too much from ours, so signed requests look expired.',
'Oc_L_F_Clock' => 'Ask the hosting provider to set the server time (NTP). A difference of a few minutes is enough to block the connection.',
'Oc_L_H_Disabled' => 'The connector module is installed in OpenCart but switched off.',
'Oc_L_F_Disabled' => 'In OpenCart open Extensions → Modules → the connector and set Status to Enabled.',
'Oc_L_H_Unreachable' => 'The store did not answer at the saved address, or the connector module is not installed there.',
'Oc_L_F_Unreachable' => 'Open the store URL in a browser to check it is online, confirm the connector module is installed and enabled, and check that no firewall or maintenance mode blocks our server.',
'Oc_L_H_Redirect' => 'The store sends visitors to another address (for example from http to https or to www).',
'Oc_L_F_Redirect' => 'Save the address named in the message as the store URL on the Connection tab.',
'Oc_L_H_Not_Configured' => 'The store URL or the secret is missing, so nothing can be sent yet.',
'Oc_L_F_Not_Configured' => 'Fill in the store URL and the secret on the Connection tab, save and run Test Connection.',
'Oc_L_H_Model_Taken' => 'A product pushed to the store has a code that another store product, or one of its variants, already uses as its model.',
'Oc_L_F_Model_Taken' => 'Change the code on one of the two products, or pull products first so the existing store product is linked instead of created again.',
'Oc_L_H_Model_Missing' => 'A product pushed to the store has no code or no name. OpenCart needs both.',
'Oc_L_F_Model_Missing' => 'Give the product a code and a name here, then push again.',
'Oc_L_H_Held' => 'An order was received but some of its items match no product here, so it is waiting and no sale was created.',
'Oc_L_F_Held' => 'Create or pull the missing products (the items are listed below), then pull orders again. Held orders are retried automatically a few times.',
'Oc_L_H_Given_Up' => 'An order could not be imported after several tries and is no longer retried.',
'Oc_L_F_Given_Up' => 'Make sure its products exist here, then pull orders by hand from the Orders tab with a date before the order.',
'Oc_L_H_Review' => 'An order was cancelled in OpenCart after the sale here was delivered or returned, so stock was not reversed automatically.',
'Oc_L_F_Review' => 'Open the sale and decide whether to return the items or leave it as it is.',
'Oc_L_H_Reversed' => 'An order was cancelled in OpenCart and the matching sale here was reversed, putting its stock back.',
'Oc_L_H_Backlog' => 'The scheduled order pull found more orders than it processes in one run and will start again next time.',
'Oc_L_F_Backlog' => 'Pull orders by hand from the Orders tab to clear the backlog.',
'Oc_L_H_Paused' => 'Automatic pushes paused for a while because the store stopped answering. Changes made meanwhile are sent once it answers again.',
'Oc_L_F_Paused' => 'Check that the store is online. Nothing else is needed; the queue resumes by itself.',
'Oc_L_H_Busy' => 'Two automatic pushes overlapped and one stepped aside. Nothing was lost.',
'Oc_L_H_Codes_Suffixed' => 'Some pulled products carry a code that another store product already had here, usually because the chosen code field is blank or holds a category name. They were created with the OpenCart id appended so no two products merge.',
'Oc_L_F_Codes_Suffixed' => 'Fill the code field (Model, SKU, ISBN…) in OpenCart for the products listed below, or choose another Product code source on the Connection tab, then reset product links and pull again.',
'Oc_L_H_Options' => 'Some store products have options (size, colour…) without variant stock, so stock is tracked for the product as a whole.',
'Oc_L_F_Options' => 'Nothing is required. To track stock per option, turn those options into variants in OpenCart 4, or use one option per product in OpenCart 3.',
'Oc_L_H_Pull_Ok' => 'This page of products was read from the store. Created means a new product here; updated means it already existed and was linked.',
'Oc_L_H_Pull_Failed' => 'Some products on this page could not be saved here; each is listed below with the reason.',
'Oc_L_F_Pull_Failed' => 'Fix the listed products in OpenCart (a missing name or code is the usual cause) and pull again. Only the failed ones are affected.',
'Oc_L_H_Push_Warnings' => 'Products were sent to the store, but the store reported problems with some of them, such as an image it could not download.',
'Oc_L_F_Push_Warnings' => 'Read the list below. Images must be reachable from the store server; anything else was saved as sent.',
'Oc_L_H_Missing_Remote' => 'Stock was pushed, but some linked products no longer exist in the store.',
'Oc_L_F_Missing_Remote' => 'Push products to recreate them in the store, or reset product links if they were deleted on purpose.',
'Oc_L_H_Generic' => 'A sync step failed. The message above is the store\'s or the server\'s own reason.',
