    'LicK_Api_Guide' => 'Licensing API guide',
    'LicK_G_Endpoints' => 'Endpoints',
    'LicK_G_Activate' => 'Bind the key to this domain or device. Uses one activation.',
    'LicK_G_Validate' => 'Check the license on this domain or device and get a fresh signed answer.',
    'LicK_G_Deactivate' => 'Release this domain or device so the activation can be used elsewhere. Never grants use.',
    'LicK_G_Status' => 'Read the license without changing anything. Never grants use (valid is always false).',
    'LicK_G_Request' => 'Request',
    'LicK_G_Request_Help' => 'Send a JSON body with license_key. product (the product code) is optional and makes sure the key belongs to your product. Send domain or device_id (+ optional device_name) — required for locked licenses and for licenses with an activation limit. Send a random nonce with every call and check it comes back in the token.',
    'LicK_G_Response' => 'Response',
    'LicK_G_Response_Help' => 'valid is true only on an activate / validate answer that allows use on this domain or device. status tells the license state. A refused answer also has error and message. The token repeats action, key_fingerprint (SHA-256 of your key, upper-cased and trimmed), identifier, nonce and host — check them.',
    'LicK_G_Errors' => 'Error codes',
    'LicK_GErr_invalid_key' => 'The key does not exist.',
    'LicK_GErr_product_mismatch' => 'The key belongs to another product.',
    'LicK_GErr_invalid_request' => 'A required field is missing or not valid.',
    'LicK_GErr_not_activated' => 'The license is not activated on this domain or device.',
    'LicK_GErr_activation_limit_reached' => 'All activations of this license are in use.',
    'LicK_GErr_license_expired' => 'The license has expired.',
    'LicK_GErr_license_suspended' => 'The license is suspended.',
    'LicK_GErr_license_revoked' => 'The license has been revoked.',
    'LicK_GErr_unavailable' => 'The licensing API is switched off or not available right now.',
    'LicK_G_Verify' => 'Verify the signature',
    'LicK_G_Verify_Help' => 'token is the answer as base64 JSON and signature is an Ed25519 signature of the token string. Verify it with the public key above and read the license ONLY from the decoded token (not from the plain fields). Accept it only when action is activate or validate, valid is true, and key_fingerprint, identifier and nonce match what you sent. Treat any other answer, or one without a signature, as not valid.',
    'LicK_G_Offline' => 'Keep the last verified token: your software may keep working without the API until offline_until.',
    'LicK_G_Rate' => 'Rate limit: 60 requests per minute per IP address.',
